@import "tailwindcss";
@import "./employee-workspace.css";
@import "./operating-doctrine.css";

:root {
  --font-geist-sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-geist-mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  --ink: #171717;
  --muted: #69737c;
  --line: #e5e7e4;
  --canvas: #f5f6f3;
  --orange: #922e26;
  --orange-soft: #f6ecea;
  --brand-gray: #58585a;
  --green: #1e8a63;
  --blue: #3478b8;
  --font-xxs: 0.375rem;
  --font-xs: 0.4375rem;
}

/* Proposal Studio v8: customer branding, team proof, intelligence review, and schedule planning. */
