/* Accountant-first forecasting, reconciliation, close, and cutover controls. */
.accounting-advanced-workspace { display: grid; gap: 18px; }
.accounting-control-tabs { display: flex; gap: 6px; padding: 6px; border: 1px solid #d8dee3; border-radius: 12px; background: #eef1f3; overflow-x: auto; }
.accounting-control-tabs button { min-height: 42px; padding: 0 18px; border: 0; border-radius: 8px; background: transparent; color: #56616b; font-weight: 800; white-space: nowrap; cursor: pointer; }
.accounting-control-tabs button.active { background: #17212b; color: #fff; box-shadow: 0 3px 10px rgba(23,33,43,.18); }
.advanced-panel { overflow: hidden; }
.advanced-panel .accounting-ledger-heading { align-items: center; gap: 20px; }
.advanced-panel .accounting-ledger-heading label { display: grid; gap: 5px; color: #66717b; font-size: 0.6875rem; font-weight: 800; text-transform: uppercase; }
.advanced-panel input,.advanced-panel select,.advanced-panel textarea,.cutover-grid input,.cutover-grid select,.collection-entry input,.collection-entry select,.forecast-entry-grid input,.forecast-entry-grid select { width: 100%; border: 1px solid #cbd2d8; border-radius: 7px; background: #fff; color: #17212b; padding: 9px 10px; font: inherit; text-transform: none; }
.advanced-table { display: grid; min-width: 980px; }
.advanced-row { display: grid; align-items: center; gap: 12px; min-height: 70px; padding: 10px 14px; border-top: 1px solid #e1e5e8; }
.advanced-row.header { min-height: 38px; background: #eef1f3; color: #5d6872; font-size: 0.625rem; font-weight: 900; letter-spacing: .07em; text-transform: uppercase; }
.advanced-row > span { min-width: 0; }
.advanced-row span b,.advanced-row span small { display: block; }
.advanced-row span small { margin-top: 4px; color: #76818a; font-size: 0.6875rem; line-height: 1.35; }
.advanced-row textarea { margin-top: 7px; resize: vertical; font-size: 0.6875rem; }
.wip-control-table { overflow-x: auto; }
.wip-control-table .advanced-row { grid-template-columns: minmax(190px,1.6fr) repeat(4,minmax(105px,.75fr)) minmax(130px,1fr) 85px minmax(150px,1.05fr); }
.advanced-actions { display: flex; flex-wrap: wrap; gap: 5px; align-items: center; }
.advanced-actions button,.modal-actions button,.control-launch-grid button,.bank-match-grid button,.collection-entry button { border: 1px solid #bec6cc; border-radius: 6px; background: #fff; color: #26313a; padding: 7px 9px; font-size: 0.6875rem; font-weight: 800; cursor: pointer; }
.advanced-actions button:disabled,.modal-actions button:disabled,.collection-entry button:disabled { opacity: .45; cursor: not-allowed; }
.close-control-table { overflow-x: auto; }
.close-control-table .advanced-row { grid-template-columns: minmax(270px,2fr) 130px 90px minmax(220px,1.5fr) 95px 150px; }
.cutover-grid,.forecast-entry-grid,.reconciliation-grid,.collection-entry { display: grid; grid-template-columns: repeat(auto-fit,minmax(180px,1fr)); gap: 12px; padding: 16px; }
.cutover-grid label,.forecast-entry-grid label,.reconciliation-grid label,.collection-entry label { display: grid; gap: 6px; color: #68727b; font-size: 0.6875rem; font-weight: 800; text-transform: uppercase; }
.cutover-checks { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 9px; padding: 0 16px 16px; }
.cutover-checks label { display: flex; gap: 10px; align-items: flex-start; min-height: 66px; padding: 12px; border: 1px solid #d9dfe3; border-radius: 8px; background: #f7f8f9; }
.cutover-checks input { width: auto; margin-top: 2px; }
.cutover-checks span b,.cutover-checks span small { display: block; }
.cutover-checks span small { margin-top: 3px; color: #77818a; font-size: 0.625rem; line-height: 1.35; }
.advanced-panel > .field-label { margin: 0 16px 16px; }
.forecast-scroll { overflow-x: auto; }
.cash-forecast-table { width: 100%; min-width: 1540px; border-collapse: collapse; font-variant-numeric: tabular-nums; }
.cash-forecast-table th,.cash-forecast-table td { padding: 11px 12px; border: 1px solid #e0e4e7; text-align: right; white-space: nowrap; }
.cash-forecast-table thead th { position: sticky; top: 0; background: #17212b; color: #fff; font-size: 0.625rem; }
.cash-forecast-table th:first-child { position: sticky; left: 0; z-index: 1; min-width: 130px; background: #eef1f3; color: #3b4650; text-align: left; }
.cash-forecast-table td.negative { background: #fff0ee; color: #a22c20; font-weight: 900; }
.forecast-entry-grid { align-items: end; }
.bank-import-paste { display: block; width: calc(100% - 32px) !important; margin: 0 16px; font-family: ui-monospace,SFMono-Regular,Menlo,monospace !important; font-size: 0.75rem !important; }
.bank-match-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; padding: 16px; }
.bank-match-grid section { padding: 12px; border: 1px solid #d9dfe3; border-radius: 9px; background: #f7f8f9; }
.bank-match-grid section h3 { margin: 0 0 10px; }
.bank-match-grid section > button { display: flex; justify-content: space-between; gap: 12px; width: 100%; margin-top: 6px; text-align: left; }
.bank-match-grid section > button.selected { border-color: #f47b20; box-shadow: 0 0 0 2px rgba(244,123,32,.16); }
.bank-match-grid button span b,.bank-match-grid button span small { display: block; }
.bank-match-grid button span small { margin-top: 3px; color: #75808a; }
.reconciliation-grid article { display: grid; align-content: center; justify-items: end; min-height: 62px; padding: 10px 13px; border-radius: 8px; }
.reconciliation-grid article.balanced { background: #e9f6ed; color: #23723a; }
.reconciliation-grid article.difference { background: #fff0ee; color: #a22c20; }
.reconciliation-grid article span { font-size: 0.625rem; font-weight: 900; text-transform: uppercase; }
.reconciliation-grid article strong { margin-top: 4px; font-size: 1.25rem; }
.aging-table { overflow-x: auto; }
.aging-table .advanced-row { grid-template-columns: minmax(210px,1.5fr) 95px 75px 110px minmax(230px,1.5fr) 75px; }
.collection-entry { align-items: end; border-top: 1px solid #dfe4e7; background: #f7f8f9; }
.vendor-tax-table { overflow-x: auto; }
.vendor-tax-table .advanced-row { grid-template-columns: minmax(220px,1.6fr) minmax(130px,1fr) 90px 100px 110px 100px; }
.control-launch-grid { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap: 12px; }
.control-launch-grid button { display: grid; gap: 6px; min-height: 110px; padding: 18px; border: 1px solid #d5dce1; background: #fff; text-align: left; }
.control-launch-grid button b { font-size: 1rem; }
.control-launch-grid button span { color: #73808a; line-height: 1.4; }
.compact-aging-list article { display: grid; grid-template-columns: 1.6fr 70px 100px 120px; gap: 10px; align-items: center; padding: 12px 14px; border-top: 1px solid #e0e5e8; }
.compact-aging-list article span b,.compact-aging-list article span small { display: block; }
.compact-aging-list article span small { color: #7a858e; }
.compact-aging-list article strong { text-align: right; }
.accounting-boundary { display: grid; grid-template-columns: auto 1fr auto; gap: 12px; align-items: center; padding: 12px 15px; border: 1px solid #d8dfe3; border-radius: 9px; background: #f6f8f9; color: #68747d; font-size: 0.6875rem; }
.accounting-boundary strong { color: #17212b; text-transform: uppercase; }
.accounting-boundary small { white-space: nowrap; }

@media (max-width: 900px) {
  .cutover-checks,.control-launch-grid,.bank-match-grid { grid-template-columns: 1fr; }
  .accounting-boundary { grid-template-columns: 1fr; }
}

