/* Item 2 · Vendor and subcontractor portal */
.vendor-management,
.vendor-tab-content,
.vendor-portal-overview,
.vendor-portal-compliance,
.vendor-portal-billing {
  display: grid;
  gap: 16px;
}
.vendor-admin-hero {
  min-height: 158px;
  border: 1px solid #d9dcda;
  border-radius: 18px;
  background: radial-gradient(circle at 88% 12%, rgba(143, 47, 39, .16), transparent 34%), linear-gradient(135deg, #fff, #f4f1ee);
  padding: 27px 30px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  box-shadow: 0 10px 28px rgba(26, 31, 34, .05);
}
.vendor-admin-hero h1,
.vendor-portal-title h1 {
  margin: 5px 0 7px;
  color: #1c2225;
  font-size: clamp(28px, 3vw, 40px);
  letter-spacing: -.04em;
}
.vendor-admin-hero p:last-child,
.vendor-portal-title > div > span {
  max-width: 720px;
  color: #69737c;
  font-size: 0.875rem;
  line-height: 1.55;
}
.vendor-admin-summary,
.vendor-portal-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}
.vendor-admin-summary article,
.vendor-portal-metrics article {
  border: 1px solid #dde1de;
  border-radius: 14px;
  background: #fff;
  padding: 17px 18px;
  display: grid;
  gap: 4px;
  box-shadow: 0 5px 18px rgba(28, 35, 39, .04);
}
.vendor-admin-summary span,
.vendor-portal-metrics span {
  color: #788188;
  font-size: 0.625rem;
  font-weight: 900;
  letter-spacing: .08em;
}
.vendor-admin-summary strong,
.vendor-portal-metrics strong {
  color: #20272b;
  font-size: 1.875rem;
  letter-spacing: -.04em;
}
