.locked-employee-identity div { display: grid; gap: 3px; }
.locked-employee-identity small { color: #d0d4d6; font-size: 0.625rem; text-transform: uppercase; letter-spacing: .08em; }
.locked-employee-shell > nav { display: flex; align-items: center; gap: 8px; padding: 14px clamp(20px, 4vw, 56px); border-bottom: 1px solid var(--line); background: #fff; }
.locked-employee-shell > nav button { padding: 10px 14px; border: 1px solid #d8d2ca; border-radius: 8px; background: #fff; color: #39434a; font-weight: 800; }
.locked-employee-shell > nav button.active { border-color: var(--orange); background: #fff4eb; color: #a84613; }
.locked-employee-shell > nav span { margin-left: auto; max-width: 560px; color: #7a5b4d; font-size: 0.6875rem; line-height: 1.5; text-align: right; }
.locked-employee-content { max-width: 1480px; margin: 0 auto; padding: clamp(20px, 4vw, 48px); }

.sidebar {
  width: 246px;
  min-height: 100vh;
  flex: 0 0 246px;
  background: #111;
  color: #fff;
  display: flex;
  flex-direction: column;
  position: sticky;
  top: 0;
  height: 100vh;
  z-index: 30;
}

.brand {
  height: 83px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 0 21px;
  border-bottom: 1px solid #2b333a;
}
.brand-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
}
.brand-mark img {
  width: 42px;
  height: 42px;
  object-fit: contain;
}
.brand div:last-child {
  display: flex;
  flex-direction: column;
  line-height: 1;
}
.brand strong {
  font-size: 1.0625rem;
  letter-spacing: 0.09em;
}
.brand span {
  margin-top: 5px;
  color: #9ca7af;
  font-size: 0.5rem;
  letter-spacing: 0.22em;
  font-weight: 700;
}

.main-nav {
  min-height: 0;
  overflow-y: auto;
  padding: 25px 12px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.nav-label {
  margin: 0 10px 10px;
  color: #707c86;
  font-size: 0.5625rem;
  letter-spacing: 0.18em;
  font-weight: 800;
}
.nav-item {
  width: 100%;
  height: 42px;
  border: 0;
  background: transparent;
  color: #aeb7be;
  border-radius: 8px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 12px;
  font-size: 0.8125rem;
  font-weight: 600;
  text-align: left;
}
.nav-item:hover {
  background: #252525;
  color: #fff;
}
.nav-item.active {
  background: #2b2b2c;
  color: #fff;
  box-shadow: inset 3px 0 0 var(--orange);
}
.nav-icon {
  width: 20px;
  height: 20px;
  border: 1px solid currentColor;
  border-radius: 5px;
  display: grid;
  place-items: center;
  font-size: 0.5625rem;
  font-weight: 800;
  opacity: 0.8;
}
.nav-count {
  margin-left: auto;
  min-width: 21px;
  height: 19px;
  border-radius: 10px;
  background: #3a454e;
  display: grid;
  place-items: center;
  font-size: 0.625rem;
}
.active .nav-count {
  background: var(--orange);
}
.nav-item + .nav-label,
.nav-folder-group + .nav-label {
  margin-top: 14px;
}
.nav-folder-group {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.nav-folder {
  width: 100%;
  height: 42px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #aeb7be;
  font-size: 0.8125rem;
  font-weight: 700;
  text-align: left;
}
.nav-folder:hover,
.nav-folder.active {
  background: #252525;
  color: #fff;
}
.nav-folder.active {
  box-shadow: inset 3px 0 0 var(--orange);
}
.nav-folder-arrow {
  margin-left: auto;
  color: #7f8990;
  font-size: 1rem;
  font-weight: 400;
}
.nav-folder-items {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 1px 0 6px 22px;
  padding-left: 10px;
  border-left: 1px solid #353535;
}
.nav-subitem {
  width: 100%;
  min-height: 34px;
  display: grid;
  grid-template-columns: 23px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #909aa1;
  text-align: left;
}
.nav-subitem > span {
  color: #7f898f;
  font-size: 0.4375rem;
  font-weight: 800;
}
.nav-subitem b {
  overflow: hidden;
  font-size: 0.6875rem;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nav-folder-empty {
  display: block;
  padding: 8px 9px 10px;
  color: #7e8983;
  font-size: 0.5625rem;
  font-weight: 700;
  line-height: 1.4;
}
.nav-subitem:hover,
.nav-subitem.active {
  background: #242425;
  color: #fff;
}
.nav-subitem.active > span {
  color: #cf7168;
}
.preconstruction-groups { gap: 3px; }
.preconstruction-group { display: grid; gap: 2px; }
.nav-subfolder {
  width: 100%;
  min-height: 37px;
  display: grid;
  grid-template-columns: 23px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: #a8b2ac;
  text-align: left;
}
.nav-subfolder > span { color: #a2ada7; font-size: 0.5625rem; font-weight: 900; }
.nav-subfolder b { font-size: 0.75rem; }
.nav-subfolder i { color: #77827c; font-size: 0.8125rem; font-style: normal; }
.nav-subfolder:hover,.nav-subfolder.active { background: rgba(255,255,255,.075); color: #fff; }
.preconstruction-group-items { display: grid; gap: 2px; margin-left: 12px; padding-left: 8px; border-left: 1px solid rgba(255,255,255,.11); }
.preconstruction-group-items .nav-subitem { min-height: 34px; }

.sidebar-bottom {
  margin-top: auto;
  padding: 12px;
  border-top: 1px solid #2b333a;
}
.user-card {
