}
.project-badge {
  width: 31px;
  height: 31px;
  border-radius: 7px;
  background: var(--orange-soft);
  color: var(--orange);
  display: grid;
  place-items: center;
  font-size: 0.625rem;
  font-weight: 800;
}
.project-switcher button > span:nth-child(2) {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.project-switcher strong {
  font-size: 0.8125rem;
}
.project-switcher small {
  color: #858e95;
  font-size: 0.5625rem;
}
.project-menu {
  width: 300px;
