}
.project-menu-label {
  color: #8a9297;
  font-size: 0.4375rem;
  font-weight: 900;
  letter-spacing: 0.08em;
}
.project-menu .project-choice {
  width: 100%;
  min-height: 52px;
  display: grid;
  grid-template-columns: 31px minmax(0, 1fr) auto;
