}
.project-menu .project-choice:hover,
.project-menu .project-choice.active {
  border-color: #c96b60;
  background: #fcf6f5;
}
.project-menu .project-choice > span:nth-child(2) {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.project-menu .project-choice b {
  color: var(--orange);
  font-size: var(--font-xs);
  letter-spacing: 0.06em;
}
.project-status {
  width: fit-content;
  border-radius: 10px;
  background: #e8f6f0;
  color: #2f7459;
  padding: 3px 6px;
  font-size: var(--font-xs);
  font-style: normal;
  font-weight: 900;
}
.project-status.preconstruction {
  background: #eef1f3;
  color: #52616a;
}
.project-status.on-hold {
  background: #fff2e4;
  color: #9a5a24;
}
.project-status.completed {
  background: #eaf3fb;
  color: #32698f;
}
.project-status.cancelled {
  background: #f7e9e7;
  color: #9a3b32;
}
.project-menu > button {
  width: 100%;
  min-height: 40px;
  display: flex;
  align-items: center;
  border: 0;
  border-bottom: 1px solid #edf0ed;
  background: white;
  padding: 0 12px;
  color: #4e5a60;
  font-size: 0.5rem;
  font-weight: 800;
}
.project-menu > button:hover {
  background: #f7f8f6;
}
.project-menu > button.start-project-action {
  background: #fcf6f5;
  color: var(--orange);
}
.chevron {
  color: #81898f;
  margin-left: 8px;
}
.topbar-actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
}
.sync-state {
  font-size: 0.625rem;
  color: #6e777e;
  margin-right: 12px;
}
.sync-state span {
  display: inline-block;
  width: 7px;
  height: 7px;
  background: #43b17c;
  border-radius: 50%;
