}
.notification {
  font-size: 0.5rem;
}
.notification > span {
  position: absolute;
  right: -4px;
  top: -5px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--orange);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 0.5rem;
  border: 2px solid #fff;
}
.primary-action {
  height: 36px;
  border: 0;
  border-radius: 7px;
  background: var(--orange);
  color: #fff;
