  opacity: 0.75;
}
.menu-button {
  display: none;
  border: 0;
  background: none;
  font-size: 1.25rem;
  margin-right: 12px;
}

.content {
  max-width: 1280px;
  margin: 0 auto;
  padding: 34px 42px 24px;
}
.welcome-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 25px;
  margin-bottom: 24px;
}
.orange-text {
  color: var(--orange);
}
.welcome-row h1 {
  margin: 7px 0 5px;
  font-size: 1.6875rem;
  letter-spacing: -0.025em;
}
.welcome-row p:last-child {
  margin: 0;
  color: #717980;
  font-size: 0.75rem;
}
.welcome-row p strong {
  color: #444f57;
}
.weather-card {
  min-width: 258px;
  height: 62px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fff;
  display: flex;
  align-items: center;
  padding: 0 15px;
  gap: 10px;
  box-shadow: 0 3px 10px rgba(27, 35, 40, 0.025);
}
.weather-icon {
  width: 34px;
  height: 34px;
  background: #fff6db;
