  color: #fff;
  padding: 12px 18px;
  border-radius: 8px;
  font-size: 0.6875rem;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.25);
  z-index: 50;
}
.scrim {
  display: none;
}

@media (max-width: 960px) {
  .dashboard-field-layout {
    grid-template-columns: 1fr;
  }
  .dashboard-log-list {
    border-right: 0;
  }
  .dashboard-field-photos {
    border-top: 1px solid #e1e4e1;
  }
  .dashboard-field-photo-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .executive-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .executive-command-grid {
    grid-template-columns: 1fr;
  }
  .executive-side-rail {
    grid-template-columns: 1fr;
  }
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .dashboard-grid {
    grid-template-columns: 1fr;
  }
  .module-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .sync-state {
    display: none;
  }
  .record-head,
  .record-row {
    grid-template-columns: 80px minmax(190px, 1fr) 105px 80px 85px 12px;
  }
  .topic-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .schedule-summary {
    grid-template-columns: repeat(2, 1fr);
  }
  .schedule-controls {
    flex-wrap: wrap;
  }
  .schedule-controls button {
    margin-left: 0;
  }
  .schedule-rules {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .file-head,
  .file-row {
