.change-order-heading p {
  max-width: 650px;
}
.change-order-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}
.change-order-summary article {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 70px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: white;
}
.change-order-summary article > span {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 9px;
  background: #f6e4e1;
  color: var(--orange);
  font-size: 0.625rem;
  font-weight: 900;
}
.change-order-summary article div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.change-order-summary strong {
  color: var(--ink);
  font-size: 1.0625rem;
}
.change-order-summary small {
  color: var(--muted);
  font-size: 0.5rem;
  font-weight: 700;
}
.change-order-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 10px;
}
.change-order-controls > label {
  display: flex;
  align-items: center;
  gap: 8px;
  width: min(360px, 100%);
  height: 38px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: white;
}
.change-order-controls input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
}
.change-order-view-toggle {
  display: flex;
  gap: 3px;
  padding: 3px;
  border-radius: 8px;
  background: #e8ebe9;
}
.change-order-view-toggle button {
  height: 30px;
  padding: 0 12px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--muted);
  font-size: 0.5rem;
  font-weight: 800;
}
.change-order-view-toggle button.active {
  background: white;
  color: var(--ink);
  box-shadow: 0 2px 6px rgba(20, 27, 30, 0.08);
}
.change-order-board {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: white;
}
.change-order-board > button {
  display: grid;
  grid-template-columns: 110px minmax(210px, 1fr) 125px 155px 135px 12px;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 70px;
  padding: 12px 14px;
  border: 0;
  border-bottom: 1px solid var(--line);
  background: white;
  color: var(--ink);
  text-align: left;
}
.change-order-board > button:last-child {
  border-bottom: 0;
}
.change-order-board > button:hover {
  background: #fffaf9;
}
.change-order-number {
  color: var(--orange);
  font-size: 0.5625rem;
  font-weight: 900;
}
.change-order-copy,
.change-order-impact,
.change-order-cost {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.change-order-copy strong,
.change-order-impact strong,
.change-order-cost strong {
  font-size: 0.625rem;
}
.change-order-copy small,
.change-order-impact small,
.change-order-cost small {
  color: var(--muted);
  font-size: 0.4375rem;
}
.change-order-cost i {
  color: #2a7f57;
  font-size: 0.4375rem;
  font-style: normal;
  font-weight: 800;
}
.change-order-permission-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 12px;
}
.change-order-permission-grid div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: #fafbf9;
}
.change-order-permission-grid strong {
  font-size: 0.5625rem;
}
.change-order-permission-grid span {
