  border: 1px solid var(--line);
  border-top: 3px solid #922e26;
  border-radius: 10px;
  background: #fff;
  padding: 17px;
  display: flex;
  flex-direction: column;
}
.sales-dashboard-metrics article > span,
.pipeline-summary-card > span {
  color: #7a858b;
  font-size: 0.5rem;
  font-weight: 900;
  letter-spacing: 0.1em;
}
.sales-dashboard-metrics article > strong,
.pipeline-summary-card > strong {
  margin: 8px 0 5px;
  color: #262e32;
  font-size: 1.4375rem;
}
.sales-dashboard-metrics article > small,
.pipeline-summary-card > small {
  color: #849096;
  font-size: 0.5625rem;
  line-height: 1.4;
}
.sales-dashboard-metrics .profit-card {
  border-top-color: #2f755b;
}
.sales-dashboard-metrics .restricted-card {
  border-top-color: #8a9296;
  background: #f4f5f3;
}
.sales-dashboard-grid {
  display: grid;
  gap: 12px;
}
.sales-chart-row {
  grid-template-columns: minmax(0, 1.65fr) minmax(300px, 0.85fr);
}
.leader-row {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.pipeline-row {
  grid-template-columns: minmax(190px, 0.55fr) minmax(190px, 0.55fr) minmax(360px, 1.3fr);
}
.sales-dashboard-card {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: #fff;
  box-shadow: 0 4px 15px rgba(26, 34, 39, 0.04);
}
.sales-dashboard-card > header {
  min-height: 64px;
  padding: 14px 17px;
  border-bottom: 1px solid #e7eae7;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.sales-dashboard-card header h2 {
  margin: 0;
  color: #2b3337;
  font-size: 0.875rem;
}
.sales-dashboard-card header p {
  margin: 4px 0 0;
  color: #899298;
  font-size: 0.5rem;
}
.sales-dashboard-card > header > span {
  color: #7e898f;
  font-size: 0.5rem;
}
.sector-history-card { margin-top: 16px; }
.sector-history-table { overflow-x: auto; }
.sector-history-table > div { min-width: 760px; padding: 11px 17px; border-bottom: 1px solid #edf0ed; display: grid; grid-template-columns: 1.2fr .85fr .65fr .9fr 1fr; align-items: center; gap: 12px; }
.sector-history-table > div:last-child { border-bottom: 0; }
.sector-history-table .sector-history-head { background: #f5f6f4; color: #687379; font-size: 0.5rem; text-transform: uppercase; }
.sector-history-table strong { color: #30393d; font-size: 0.6875rem; }
.sector-history-table span { color: #59666c; font-size: 0.625rem; }
.monthly-sales-chart {
  height: 235px;
  padding: 22px 16px 14px;
  display: grid;
  grid-template-columns: repeat(12, minmax(24px, 1fr));
  gap: 7px;
  align-items: end;
  overflow-x: auto;
}
.month-column {
  min-width: 34px;
  height: 100%;
  display: grid;
  grid-template-rows: 24px 1fr 18px;
  justify-items: center;
  align-items: end;
}
.month-value {
  color: #4f5a60;
  font-size: 0.4375rem;
  font-weight: 800;
}
.month-bars {
  width: 100%;
  height: 155px;
  display: flex;
  align-items: end;
  justify-content: center;
  gap: 2px;
  border-bottom: 1px solid #d8ddda;
  background: repeating-linear-gradient(to top, transparent 0, transparent 38px, #eef0ee 39px);
}
.month-bars span {
  width: 35%;
  min-height: 2px;
  display: block;
  border-radius: 3px 3px 0 0;
}
.month-goal-bar {
  background: #d2d7d4;
}
.month-sales-bar {
  background: #922e26;
}
.month-column small {
  color: #727d83;
  font-size: 0.4375rem;
  font-weight: 800;
}
.quarter-grid {
  padding: 17px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 11px;
}
.quarter-grid > div {
  border: 1px solid #e1e5e2;
  border-radius: 8px;
  padding: 12px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 8px;
}
.quarter-grid span {
  color: #922e26;
  font-size: 0.5625rem;
  font-weight: 900;
}
.quarter-grid strong {
  grid-column: 1 / -1;
  font-size: 1.0625rem;
}
.quarter-grid small {
  color: #879197;
  font-size: 0.5rem;
}
.quarter-grid > div > div {
  grid-column: 1 / -1;
  height: 6px;
  overflow: hidden;
  border-radius: 99px;
  background: #e7eae8;
}
.quarter-grid i {
  height: 100%;
  display: block;
  background: #922e26;
}
.quarter-grid b {
  color: #59646a;
  font-size: 0.5rem;
}
.leader-list {
  min-height: 190px;
  padding: 6px 16px 13px;
}
.leader-list > div {
  min-height: 56px;
  border-bottom: 1px solid #edf0ed;
  display: grid;
  grid-template-columns: 28px 1fr auto;
  align-items: center;
  gap: 9px;
}
.leader-list > div:last-child {
  border-bottom: 0;
}
.leader-list > div > span {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--orange-soft);
  color: var(--orange);
  display: grid;
  place-items: center;
  font-size: 0.5rem;
  font-weight: 900;
}
.leader-list > div > div {
  display: flex;
  flex-direction: column;
}
.leader-list strong {
  color: #30383c;
  font-size: 0.625rem;
}
.leader-list small {
  margin-top: 3px;
  color: #899298;
  font-size: 0.5rem;
}
.leader-list b {
  color: #273034;
  font-size: 0.6875rem;
}
.dashboard-empty-copy {
  margin: 0;
  padding: 38px 20px;
  color: #899399;
  text-align: center;
  font-size: 0.5625rem;
}
.pipeline-summary-card {
  min-height: 128px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.recent-wins-card > div {
  min-height: 43px;
  padding: 9px 16px;
  border-top: 1px solid #edf0ed;
  display: grid;
  grid-template-columns: 75px 1fr auto;
  align-items: center;
  gap: 10px;
}
.recent-wins-card > div > span {
  color: #879197;
  font-size: 0.5rem;
}
.recent-wins-card > div > strong,
.recent-wins-card > div > b {
  color: #30383c;
  font-size: 0.625rem;
}
.company-contact-groups {
  padding: 13px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.company-contact-groups > section {
  overflow: hidden;
  border: 1px solid #e0e4e1;
  border-radius: 9px;
}
.company-contact-groups > section > header {
  padding: 11px 14px;
  background: #f4f5f3;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.company-contact-groups header div {
  display: flex;
  flex-direction: column;
}
.company-contact-groups header span,
.company-contact-groups header small {
  color: #899298;
  font-size: 0.5rem;
}
.company-contact-groups header strong {
  margin-top: 3px;
  color: #293135;
  font-size: 0.75rem;
}
.company-contact-groups section > div > button {
  width: 100%;
  min-height: 60px;
  border: 0;
  border-top: 1px solid #edf0ed;
  background: #fff;
  padding: 10px 14px;
  display: grid;
  grid-template-columns: 1.1fr 1.2fr 1fr auto;
  align-items: center;
  gap: 14px;
  text-align: left;
}
.company-contact-groups section > div > button:hover {
  background: #fbf7f6;
}
.company-contact-groups button > span {
  display: flex;
  flex-direction: column;
}
.company-contact-groups button strong {
  color: #30383c;
  font-size: 0.625rem;
}
.company-contact-groups button small {
  margin-top: 3px;
  color: #879197;
  font-size: 0.5rem;
}
.company-contact-groups .crm-status {
  font-style: normal;
}
.opportunity-contact-select {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 7px;
}
.opportunity-contact-select button {
  border: 1px solid #d3aaa6;
  border-radius: 7px;
  background: var(--orange-soft);
  color: var(--orange);
  padding: 0 10px;
  font-size: 0.5rem;
  font-weight: 800;
  white-space: nowrap;
}
.sales-goal-admin-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 14px;
}
.goal-company-card > label,
.goal-people-card > div {
  margin: 18px;
}
.goal-company-card > label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: #68747a;
  font-size: 0.5625rem;
  font-weight: 800;
}
.goal-company-card label > div,
.goal-people-card label > div {
  height: 46px;
  border: 1px solid #d8ddda;
  border-radius: 8px;
  display: flex;
  align-items: center;
  padding: 0 11px;
}
.goal-company-card label b,
.goal-people-card label b {
  color: #7c878d;
  font-size: 0.8125rem;
}
.goal-company-card input,
.goal-people-card input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  padding: 0 6px;
  color: #283136;
  font-size: 1.0625rem;
  font-weight: 800;
}
.goal-quarter-preview {
  margin: 0 18px 18px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.goal-quarter-preview > span {
  border: 1px solid #e2e5e3;
  border-radius: 7px;
  padding: 10px;
  display: flex;
  flex-direction: column;
}
.goal-quarter-preview small {
  color: #922e26;
  font-size: 0.5rem;
  font-weight: 900;
}
.goal-quarter-preview strong {
  margin-top: 4px;
  font-size: 0.6875rem;
}
.goal-people-card > div > label {
  padding: 10px 0;
  border-bottom: 1px solid #edf0ed;
  display: grid;
  grid-template-columns: 1fr 185px;
  align-items: center;
  gap: 16px;
}
.goal-people-card label > span {
  display: flex;
  flex-direction: column;
}
.goal-people-card label span strong {
  color: #30383c;
  font-size: 0.625rem;
}
.goal-people-card label span small {
  margin-top: 3px;
  color: #889298;
  font-size: 0.5rem;
}
.goal-warning,
.goal-match {
  margin: 0 18px 18px;
  border-radius: 7px;
  padding: 9px 11px;
  font-size: 0.5rem;
  font-weight: 800;
}
.goal-warning {
  background: #fff5e8;
  color: #865d28;
}
.goal-match {
  background: #eaf6f0;
  color: #21684e;
}
.goal-policy-card {
  padding: 17px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}
.goal-policy-card > div {
  display: flex;
  flex-direction: column;
}
.goal-policy-card strong {
  color: #30383c;
  font-size: 0.6875rem;
}
.goal-policy-card small {
  max-width: 720px;
  margin-top: 4px;
  color: #7f8a90;
  font-size: 0.5625rem;
  line-height: 1.45;
}
.sales-goal-restricted {
  padding: 35px;
  text-align: center;
}
.sales-goal-restricted strong {
  font-size: 1rem;
}
.sales-goal-restricted p {
  max-width: 620px;
  margin: 8px auto 0;
  color: #7e898f;
  font-size: 0.625rem;
}

.estimate-workspace-layer {
  position: fixed;
  inset: 0;
  z-index: 110;
  overflow: auto;
  background: #f2f3f0;
}
.estimate-workspace-shell {
  min-width: 880px;
  min-height: 100vh;
}
.estimate-workspace-header {
  position: sticky;
  top: 0;
  z-index: 5;
  min-height: 78px;
  padding: 15px 28px;
  border-bottom: 1px solid #d9ddda;
  background: rgba(255, 255, 255, 0.97);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  box-shadow: 0 3px 13px rgba(25, 33, 37, 0.05);
}
.estimate-workspace-header > div {
  display: grid;
  grid-template-columns: auto auto auto;
  align-items: center;
  gap: 7px;
}
.estimate-workspace-header > div > button {
  border: 0;
  background: transparent;
  color: var(--orange);
  padding: 0;
  font-size: 0.625rem;
  font-weight: 800;
}
.estimate-workspace-header > div > span {
  color: #929b9f;
}
.estimate-workspace-header > div > strong {
  color: #242b2f;
  font-size: 0.6875rem;
}
.estimate-workspace-header p {
  grid-column: 1 / -1;
  margin: 4px 0 0;
  color: #7d878c;
  font-size: 0.5625rem;
}
.estimate-workspace-close {
  width: 36px;
  height: 36px;
  border: 1px solid #d9ddda;
  border-radius: 8px;
  background: #fff;
  color: #4d585e;
  font-size: 1.375rem;
}
.estimate-workspace-notice {
  position: sticky;
  top: 78px;
  z-index: 4;
  border-radius: 0;
}
.estimate-workspace-intro {
  max-width: 1160px;
  margin: 0 auto;
  padding: 28px 30px 18px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 28px;
}
.estimate-workspace-intro h1 {
  margin: 6px 0 5px;
  color: #20272b;
  font-size: 1.6875rem;
  letter-spacing: -0.03em;
}
.estimate-workspace-intro > div:first-child > span {
  color: #737d83;
  font-size: 0.625rem;
}
.estimate-workspace-stats {
  display: flex;
  gap: 8px;
}
.estimate-workspace-stats > span {
  min-width: 135px;
  min-height: 58px;
  border: 1px solid #dce0dd;
  border-radius: 8px;
  background: #fff;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
}
.estimate-workspace-stats small,
.live-estimate-file > span small {
  color: #858f94;
  font-size: 0.4375rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.estimate-workspace-stats strong,
.live-estimate-file > span strong {
  margin-top: 5px;
  color: #272e32;
  font-size: 0.6875rem;
}
.estimate-folder-list {
  max-width: 1160px;
  margin: 0 auto;
  padding: 0 30px 42px;
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.estimate-folder {
  overflow: hidden;
  border: 1px solid #d9ddda;
  border-radius: 8px;
  background: #fff;
  box-shadow: 0 2px 7px rgba(25, 33, 37, 0.025);
}
.estimate-folder.open {
  border-color: #caa09c;
  box-shadow: 0 5px 16px rgba(85, 39, 34, 0.06);
}
.estimate-folder-row {
  width: 100%;
  min-height: 58px;
  border: 0;
  background: #f7f8f6;
  padding: 8px 14px;
  display: grid;
  grid-template-columns: 16px 38px minmax(280px, 1fr) 76px 96px;
  align-items: center;
  gap: 10px;
  color: #343b3f;
  text-align: left;
}
.estimate-folder.open .estimate-folder-row {
  border-bottom: 1px solid #e2e5e2;
  background: #f2f3f1;
}
.folder-chevron {
  color: #70797e;
  font-size: 1.5rem;
  transform: rotate(0deg);
  transition: transform 0.15s ease;
}
.estimate-folder.open .folder-chevron {
  transform: rotate(90deg);
}
.estimate-folder-icon {
  position: relative;
  width: 34px;
  height: 25px;
  border-radius: 4px;
  background: #6d7478;
  box-shadow: inset 0 -2px 0 rgba(0, 0, 0, 0.12);
}
.estimate-folder-icon::before {
  content: "";
  position: absolute;
  top: -5px;
  left: 3px;
  width: 15px;
  height: 7px;
  border-radius: 3px 3px 0 0;
  background: #6d7478;
}
.estimate-folder-row strong {
  font-size: 0.875rem;
  font-weight: 750;
}
.estimate-folder-row small {
  color: #7f898e;
  font-size: 0.5625rem;
}
.folder-open-label {
  color: var(--orange);
  text-align: right;
  font-size: 0.5rem;
  font-weight: 800;
}
.estimate-folder-contents {
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.live-estimate-file {
  min-height: 74px;
  border: 1px solid #d8b2ae;
  border-left: 4px solid var(--orange);
  border-radius: 8px;
  background: #fcf7f6;
  padding: 11px 13px;
  display: grid;
  grid-template-columns: 42px minmax(250px, 1fr) 120px 120px 112px;
  align-items: center;
  gap: 13px;
}
.live-estimate-icon {
  width: 39px;
  height: 45px;
  border-radius: 5px;
  background: var(--orange);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 0.5rem;
  font-weight: 900;
}
.live-estimate-file > div,
.live-estimate-file > span {
  display: flex;
  flex-direction: column;
}
.live-estimate-file > div strong {
  color: #2a3135;
  font-size: 0.6875rem;
}
.live-estimate-file > div small {
  margin-top: 5px;
  color: #777f84;
  font-size: 0.5rem;
  line-height: 1.4;
}
.live-estimate-file > button {
  border: 0;
  border-radius: 7px;
  background: var(--orange);
  color: #fff;
  padding: 9px;
  font-size: 0.5625rem;
  font-weight: 800;
}
.estimate-uploaded-file {
  width: 100%;
  min-height: 59px;
  border: 1px solid #e0e4e1;
  border-radius: 7px;
  background: #fff;
  padding: 9px 12px;
  display: grid;
  grid-template-columns: 36px 1fr auto;
  align-items: center;
  gap: 11px;
  text-align: left;
}
.estimate-uploaded-file:hover {
  border-color: #c9a29e;
  background: #fcf9f8;
}
.estimate-uploaded-file > span {
  width: 33px;
  height: 38px;
  border-radius: 4px;
  background: #eceeed;
  color: #5a656b;
  display: grid;
  place-items: center;
  font-size: 0.4375rem;
  font-weight: 900;
}
.estimate-uploaded-file > div {
  display: flex;
  flex-direction: column;
}
.estimate-uploaded-file strong {
  color: #2b3236;
  font-size: 0.625rem;
}
.estimate-uploaded-file small {
  margin-top: 4px;
  color: #7f898e;
  font-size: 0.5rem;
}
.estimate-uploaded-file b {
  color: var(--orange);
  font-size: 0.5rem;
}
.estimate-folder-drop {
  min-height: 68px;
  border: 1px dashed #bdc4c0;
  border-radius: 7px;
  background: #fafbf9;
  padding: 11px 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 11px;
  color: #59646a;
  cursor: pointer;
}
.estimate-folder-drop.dragging {
  border-color: var(--orange);
  background: var(--orange-soft);
  box-shadow: inset 0 0 0 2px rgba(146, 46, 38, 0.08);
}
.estimate-folder-drop input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}
.estimate-folder-drop > span {
  width: 31px;
  height: 31px;
  border-radius: 50%;
  background: var(--orange-soft);
  color: var(--orange);
  display: grid;
  place-items: center;
  font-size: 1.0625rem;
  font-weight: 800;
}
.estimate-folder-drop > div {
  display: flex;
  flex-direction: column;
}
.estimate-folder-drop strong {
  color: #3d474c;
  font-size: 0.5625rem;
}
.estimate-folder-drop small {
  margin-top: 4px;
  color: #828c91;
  font-size: 0.5rem;
}
.estimate-quotes-rule {
  min-height: 82px;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 14px 16px;
  border: 1px solid #d8c4c0;
  border-left: 4px solid #9b352d;
  border-radius: 11px;
  background: #fff8f7;
}
.estimate-quotes-rule > span {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #91342c;
  color: #fff;
  font-size: 0.625rem;
  font-weight: 950;
  letter-spacing: .08em;
}
.estimate-quotes-rule > div { display: grid; gap: 4px; }
.estimate-quotes-rule strong { color: #2e3732; font-size: 0.75rem; }
.estimate-quotes-rule small { max-width: 760px; color: #6d7771; font-size: 0.625rem; line-height: 1.5; }

@media (max-width: 980px) {
  .sales-summary-grid,
  .sales-summary-grid.four {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .sales-heading {
    align-items: flex-start;
  }
  .sales-goal-hero {
    grid-template-columns: 1fr 1.2fr;
  }
  .sales-goal-balance {
    grid-column: 1 / -1;
    padding: 15px 0 0;
    border-left: 0;
    border-top: 1px solid rgba(255,255,255,0.14);
  }
  .sales-dashboard-metrics,
  .sales-chart-row,
  .pipeline-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .monthly-sales-card,
  .recent-wins-card {
    grid-column: 1 / -1;
  }
}

@media (max-width: 620px) {
  .sales-heading,
  .estimating-heading,
  .sales-panel-heading,
  .funnel-toolbar {
    align-items: stretch;
    flex-direction: column;
  }
  .sales-heading .primary-action,
  .sales-search {
    width: 100%;
  }
  .sales-summary-grid,
  .sales-summary-grid.four,
  .sales-form-grid {
    grid-template-columns: 1fr;
  }
  .sales-field-wide {
    grid-column: auto;
  }
  .business-card-intake > header {
    align-items: stretch;
    flex-direction: column;
  }
  .business-card-capture b {
    width: 100%;
  }
  .business-card-detected {
    grid-template-columns: 1fr;
  }
  .sales-modal-actions,
  .sales-modal-actions.split {
    flex-wrap: wrap;
  }
  .sales-modal-actions.split > span {
    display: none;
  }
  .sales-modal-actions button {
    flex: 1 1 140px;
  }
  .estimate-template-note {
    max-width: none;
  }
  .sales-heading-actions,
  .estimating-heading-actions {
    align-items: stretch;
    flex-direction: column;
  }
  .sales-heading-actions > *,
  .estimating-heading-actions > * {
    width: 100%;
  }
  .sales-goal-hero,
  .sales-dashboard-metrics,
  .sales-chart-row,
  .leader-row,
  .pipeline-row,
  .sales-goal-admin-grid {
    grid-template-columns: 1fr;
  }
  .sales-goal-hero {
    padding: 21px;
  }
  .sales-goal-progress,
  .sales-goal-balance,
  .monthly-sales-card,
  .recent-wins-card {
    grid-column: auto;
  }
  .monthly-sales-chart {
    grid-template-columns: repeat(12, 38px);
  }
  .company-contact-groups section > div > button {
    grid-template-columns: 1fr;
  }
  .opportunity-contact-select,
  .goal-people-card > div > label {
    grid-template-columns: 1fr;
  }
  .goal-policy-card {
    align-items: stretch;
    flex-direction: column;
  }
}

