.accounting-hero {
  min-height: 150px;
  border: 1px solid #d9dcda;
  border-radius: 18px;
  background:
    radial-gradient(circle at 86% 12%, rgba(146, 46, 38, 0.14), transparent 34%),
    linear-gradient(135deg, #ffffff 0%, #f5f2ef 100%);
  padding: 28px 30px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  box-shadow: 0 10px 28px rgba(26, 31, 34, 0.05);
}
.accounting-hero h1 {
  margin: 5px 0 7px;
  color: #1c2225;
  font-size: clamp(27px, 3vw, 40px);
  letter-spacing: -0.04em;
}
.accounting-hero p:last-child {
  max-width: 690px;
  margin: 0;
  color: #69737c;
  font-size: 0.875rem;
  line-height: 1.6;
}
.accounting-test-badge {
  border: 1px solid #cfa19c;
  border-radius: 999px;
  background: #fff7f5;
  color: #7f271f;
  padding: 9px 12px;
  font-size: 0.5625rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  white-space: nowrap;
}
.accounting-notice {
  border: 1px solid #d9b5af;
  border-radius: 10px;
  background: #fff8f6;
  color: #72261f;
  padding: 12px 15px;
  font-size: 0.75rem;
  font-weight: 800;
}
.accounting-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}
.accounting-summary-grid article {
  min-height: 118px;
  border: 1px solid #dfe2df;
  border-radius: 14px;
  background: #fff;
  padding: 18px;
  display: flex;
  flex-direction: column;
  box-shadow: 0 5px 18px rgba(28, 35, 39, 0.04);
}
.accounting-summary-grid article > span {
  color: #788188;
  font-size: 0.5625rem;
  font-weight: 900;
  letter-spacing: 0.08em;
}
.accounting-summary-grid article > strong {
  margin: 9px 0 3px;
  color: #20272b;
  font-size: 1.875rem;
  letter-spacing: -0.04em;
}
.accounting-summary-grid article > small {
  color: #7b8489;
  font-size: 0.625rem;
}
.accounting-control-strip {
  border: 1px solid #dcdedc;
  border-left: 4px solid var(--orange);
  border-radius: 12px;
  background: #fff;
  padding: 15px 17px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.accounting-control-strip > div {
  margin-right: auto;
  display: grid;
  gap: 3px;
}
.accounting-control-strip strong {
  color: #242b2e;
  font-size: 0.8125rem;
}
.accounting-control-strip span {
  color: #768087;
  font-size: 0.625rem;
}
.accounting-special-controls {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}
.accounting-special-controls article {
  border: 1px solid #dde0dd;
  border-radius: 12px;
  background: #fafbf9;
  padding: 13px;
  display: flex;
  align-items: center;
  gap: 11px;
}
.accounting-special-controls article > b {
  min-width: 52px;
  border-radius: 8px;
  background: #252a2c;
  color: white;
  padding: 9px 7px;
  text-align: center;
  font-size: 0.625rem;
}
.accounting-special-controls article > span {
  display: grid;
  gap: 2px;
}
.accounting-special-controls strong {
  color: #303638;
  font-size: 0.625rem;
}
.accounting-special-controls small {
  color: #7e878b;
  font-size: 0.5rem;
  line-height: 1.35;
}
.accounting-ledger-panel,
.accounting-rules-panel,
.report-selection-panel,
