.accounting-workflow-grid p {
  margin: 7px 0 14px;
  color: #727c81;
  font-size: 0.625rem;
  line-height: 1.5;
}
.accounting-workflow-grid i {
  width: fit-content;
  margin-top: auto;
  border-radius: 999px;
  background: #f5ecea;
  color: #842d25;
