  display: grid;
  grid-template-columns: minmax(220px, 0.7fr) minmax(0, 1.3fr);
  gap: 30px;
}
.accounting-rules-panel h2 {
  margin: 5px 0;
  font-size: 1.25rem;
}
.accounting-rules-panel > div > span {
  color: #7c858a;
  font-size: 0.625rem;
}
