  display: grid;
  gap: 3px;
}
.report-selection-panel strong {
  font-size: 0.75rem;
}
.report-selection-panel span {
  color: #7a8488;
  font-size: 0.5625rem;
}
.report-selection-panel > div:last-child {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.report-selection-panel label {
  border: 1px solid #dcdedc;
  border-radius: 8px;
  background: #fafbf9;
  padding: 8px 9px;
  display: flex;
  align-items: center;
  gap: 6px;
  color: #4c555a;
  font-size: 0.5625rem;
  font-weight: 800;
