.schedule-print-sheet {
  display: none;
}

.people-workspace {
  display: grid;
  gap: 18px;
  padding-bottom: 42px;
}
.people-hero {
  min-height: 172px;
  border: 1px solid #d9dcda;
  border-left: 5px solid var(--orange);
  border-radius: 18px;
  background:
    radial-gradient(circle at 89% 10%, rgba(146, 46, 38, 0.15), transparent 34%),
    linear-gradient(135deg, #fff 0%, #f4f2ef 100%);
  padding: 29px 31px;
  display: flex;
  justify-content: space-between;
  gap: 25px;
  box-shadow: 0 10px 28px rgba(26, 31, 34, 0.05);
}
.people-hero h1 {
  margin: 5px 0 8px;
  color: #1d2326;
  font-size: clamp(28px, 3vw, 42px);
  letter-spacing: -0.045em;
}
.people-hero p:last-child {
  max-width: 720px;
  margin: 0;
  color: #69747a;
  font-size: 0.8125rem;
  line-height: 1.65;
}
.people-hero-status {
  min-width: 150px;
  align-self: center;
  border: 1px solid #d9bab5;
  border-radius: 14px;
  background: rgba(255,255,255,.8);
  padding: 17px;
  display: grid;
  gap: 3px;
  text-align: center;
}
.people-hero-status span {
  color: var(--orange);
  font-size: 1.5rem;
  font-weight: 900;
}
.people-hero-status strong { color: #30373a; font-size: 0.625rem; }
.people-hero-status small { color: #7d868b; font-size: 0.5rem; }
.employee-lock-banner {
  border: 1px solid #c78a83;
  border-radius: 15px;
  background: #fff4f1;
  padding: 18px;
  display: grid;
  grid-template-columns: 46px 1fr auto;
  gap: 15px;
  align-items: center;
}
.employee-lock-banner > span {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: var(--orange);
  display: grid;
  place-items: center;
  font-size: 1.25rem;
}
.employee-lock-banner h2 { margin: 3px 0; color: #69251f; font-size: 1.125rem; }
.employee-lock-banner p { margin: 0; color: #80534f; font-size: 0.625rem; }
.employee-lock-banner > b {
  border-radius: 999px;
  background: #fff;
  color: #7e2b24;
  padding: 8px 11px;
  font-size: 0.5rem;
}
.people-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  gap: 10px;
}
.people-summary-grid article {
  min-height: 108px;
  border: 1px solid #dee1df;
  border-radius: 14px;
  background: #fff;
  padding: 17px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  box-shadow: 0 5px 16px rgba(28,35,39,.04);
}
.people-summary-grid span,
.employee-cycle-grid article > span {
  color: #7c858a;
  font-size: 0.5rem;
  font-weight: 900;
  letter-spacing: .08em;
}
.people-summary-grid strong {
  margin: 6px 0 2px;
  color: #272e31;
  font-size: 1.8125rem;
}
.people-summary-grid small { color: #7d878c; font-size: 0.5rem; }
.people-alert-card { border-color: #d19a93 !important; background: #fff7f5 !important; }
.people-alert-card strong { color: var(--orange) !important; }
.people-admin-toolbar {
  border: 1px solid #dfe2df;
  border-radius: 14px;
  background: #fff;
  padding: 17px 19px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}
.people-admin-toolbar h2 { margin: 2px 0; color: #2a3134; font-size: 1.1875rem; }
.people-admin-toolbar span { color: #768086; font-size: 0.5625rem; }
.people-management-grid {
  display: grid;
  grid-template-columns: minmax(330px,.78fr) minmax(520px,1.4fr);
  gap: 13px;
  align-items: start;
}
.employee-roster,
.employee-onboarding-detail,
.onboarding-template-panel,
.renewal-communication-panel {
  border: 1px solid #dce0dd;
  border-radius: 15px;
  background: #fff;
  overflow: hidden;
  box-shadow: 0 6px 20px rgba(26,31,34,.04);
}
.employee-roster-head {
  min-height: 50px;
  padding: 14px 16px;
  border-bottom: 1px solid #e6e9e6;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.employee-roster-head strong { color: #30373a; font-size: 0.75rem; }
.employee-roster-head span { color: #828b90; font-size: 0.5rem; }
.employee-roster > button {
  width: 100%;
  min-height: 76px;
  border: 0;
  border-bottom: 1px solid #eceeec;
  background: #fff;
  padding: 10px 13px;
  display: grid;
  grid-template-columns: 38px minmax(0,1fr) auto;
  gap: 10px;
  align-items: center;
  text-align: left;
}
.employee-roster > button.selected { background: #f6eeec; box-shadow: inset 4px 0 var(--orange); }
.employee-roster > button > i,
.employee-detail-identity > i {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: #2c3235;
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 0.5625rem;
  font-style: normal;
  font-weight: 900;
}
.employee-roster > button > span { min-width: 0; display: grid; gap: 3px; }
.employee-roster > button > span strong { overflow: hidden; color: #333b3e; font-size: 0.625rem; text-overflow: ellipsis; white-space: nowrap; }
.employee-roster > button > span small { overflow: hidden; color: #7c868b; font-size: 0.4375rem; text-overflow: ellipsis; white-space: nowrap; }
.employee-roster > button > em {
  grid-column: 3;
  color: #727c81;
  font-size: 0.4375rem;
  font-style: normal;
  text-align: right;
}
.people-status {
  border-radius: 999px;
  background: #edf0ed;
  color: #5a656a;
  padding: 6px 8px;
  font-size: 0.4375rem;
  font-weight: 900;
  white-space: nowrap;
}
.people-status.active,
.people-status.extension-active { background: #e4f3eb; color: #176445; }
.people-status.annual-renewal-due,
.people-status.ready-for-activation,
.people-status.ready-for-reactivation { background: #fff1d8; color: #865900; }
.people-status.onboarding-required,
.people-status.locked-for-annual-renewal,
.people-status.terminated { background: #f8e4e1; color: #862e27; }
.people-status.hire-date-required { background: #edf0f2; color: #5b676e; }
.employee-onboarding-detail > header {
  min-height: 73px;
  padding: 14px 17px;
  border-bottom: 1px solid #e7e9e7;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}
.employee-detail-identity { display: flex; align-items: center; gap: 11px; }
.employee-detail-identity > i { width: 42px; height: 42px; background: var(--orange); }
.employee-detail-identity h2 { margin: 2px 0; color: #293034; font-size: 1.0625rem; }
.employee-detail-identity small { color: #7d868b; font-size: 0.5rem; }
.employee-cycle-grid {
  padding: 13px;
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 9px;
  background: #f7f8f6;
}
.employee-cycle-grid article {
  min-height: 91px;
  border: 1px solid #e1e4e1;
  border-radius: 11px;
  background: #fff;
  padding: 12px;
  display: grid;
  align-content: center;
  gap: 5px;
}
.employee-cycle-grid strong { color: #30373a; font-size: 0.875rem; }
.employee-cycle-grid small { color: #838c91; font-size: 0.4375rem; }
.employee-cycle-grid article > div:first-of-type { display: grid; grid-template-columns: 1fr auto; gap: 5px; }
.employee-cycle-grid input { min-width: 0; border: 1px solid #d9ddda; border-radius: 6px; padding: 6px; font-size: 0.5rem; }
.employee-cycle-grid button { border: 0; border-radius: 6px; background: #eee3e1; color: #812c24; padding: 6px; font-size: 0.4375rem; font-weight: 900; }
.people-progress { height: 6px; border-radius: 99px; background: #e6e9e6; overflow: hidden; }
.people-progress i { height: 100%; display: block; border-radius: inherit; background: var(--orange); }
.employee-extension-note {
  margin: 13px 15px 0;
  border: 1px solid #dfbf81;
  border-radius: 9px;
  background: #fff8e9;
  padding: 10px 12px;
  display: grid;
  gap: 3px;
}
.employee-extension-note strong { color: #76500a; font-size: 0.5625rem; }
.employee-extension-note span { color: #806b40; font-size: 0.5rem; }
.employee-requirement-heading {
  padding: 14px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.employee-requirement-heading > div { display: grid; gap: 2px; }
.employee-requirement-heading strong { color: #333a3e; font-size: 0.6875rem; }
.employee-requirement-heading span { color: #7e888d; font-size: 0.5rem; }
.employee-requirement-list { border-top: 1px solid #e8eae8; }
.employee-requirement-list article {
  min-height: 67px;
  padding: 10px 14px;
  border-bottom: 1px solid #eceeec;
  display: grid;
  grid-template-columns: 33px minmax(0,1fr) auto;
  gap: 10px;
  align-items: center;
}
.employee-requirement-list article.complete { background: #f7fbf8; }
.employee-requirement-list article > span {
  width: 31px;
  height: 31px;
  border-radius: 8px;
  background: #ede3e1;
  color: #7d2b24;
  display: grid;
  place-items: center;
  font-size: 0.5rem;
  font-weight: 900;
}
.employee-requirement-list article.complete > span { background: #dff0e7; color: #176345; }
.employee-requirement-list article > div { min-width: 0; display: grid; gap: 2px; }
.employee-requirement-list strong { color: #374044; font-size: 0.5625rem; }
.employee-requirement-list small { color: #7b858a; font-size: 0.4375rem; }
.employee-requirement-list em { color: #99715f; font-size: 0.4375rem; font-style: normal; }
.employee-requirement-list article.complete em { color: #3d7a61; }
.employee-requirement-list button {
  border: 1px solid #d7b5b0;
  border-radius: 7px;
  background: #fff;
  color: #812d25;
  padding: 7px 9px;
  font-size: 0.4375rem;
  font-weight: 900;
}
.employee-requirement-list article > b { color: #247253; font-size: 0.4375rem; }
.employee-onboarding-detail > footer { padding: 13px 15px; display: flex; justify-content: flex-end; gap: 8px; }
.danger-outline-action {
  border: 1px solid #c98881;
  border-radius: 7px;
  background: #fff;
  color: #8a2d25;
  padding: 8px 11px;
  font-size: 0.5rem;
  font-weight: 900;
}
.onboarding-template-panel > header {
  padding: 17px 19px;
  display: flex;
  justify-content: space-between;
  gap: 15px;
  align-items: center;
}
.onboarding-template-panel h2 { margin: 3px 0; color: #2d3538; font-size: 1.125rem; }
.onboarding-template-panel header span { color: #7c858a; font-size: 0.5rem; }
.template-requirement-head,
.template-requirement-row {
  min-height: 44px;
  padding: 7px 16px;
  display: grid;
  grid-template-columns: minmax(230px,1.4fr) minmax(130px,.8fr) minmax(130px,.8fr) minmax(120px,.7fr) 95px;
  gap: 10px;
  align-items: center;
  border-top: 1px solid #e9ebe9;
}
.template-requirement-head { min-height: 34px; background: #2d3235; }
.template-requirement-head span { color: #fff; font-size: 0.4375rem; font-weight: 900; letter-spacing: .05em; }
.template-requirement-row:nth-child(odd) { background: #fafbf9; }
.template-requirement-row > span { color: #606b70; font-size: 0.5rem; }
.template-requirement-row > span:first-child { display: grid; gap: 2px; }
.template-requirement-row b { color: #364044; font-size: 0.5625rem; }
.template-requirement-row small { color: #818b90; font-size: 0.4375rem; }
.content-status { justify-self: start; border-radius: 99px; padding: 6px 8px; font-size: 0.4375rem !important; }
.content-status.ready { background: #e2f1e9; color: #1d6c4e; }
.content-status.draft { background: #fff0db; color: #845700; }
.onboarding-template-panel > footer {
  padding: 14px 17px;
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 12px;
  background: #f7f8f6;
}
.onboarding-template-panel footer > div { display: grid; gap: 3px; }
.onboarding-template-panel footer strong { color: #424b4f; font-size: 0.5625rem; }
.onboarding-template-panel footer span { color: #7a8489; font-size: 0.5rem; line-height: 1.45; }
.renewal-communication-panel {
  padding: 16px;
  display: grid;
  grid-template-columns: repeat(4,minmax(130px,1fr) 20px) auto;
  gap: 8px;
  align-items: center;
}
.renewal-communication-panel > div { min-height: 73px; border: 1px solid #e0e3e0; border-radius: 10px; padding: 10px; display: grid; align-content: center; gap: 2px; }
.renewal-communication-panel > div span { color: var(--orange); font-size: 1.125rem; font-weight: 900; }
.renewal-communication-panel > div strong { color: #3b4347; font-size: 0.5rem; }
.renewal-communication-panel > div small { color: #7f888d; font-size: 0.4375rem; }
.renewal-communication-panel > i { color: #a2a9ac; font-style: normal; text-align: center; }
.renewal-communication-panel > b { border-radius: 99px; background: #f7e9e7; color: #7f2a23; padding: 8px 10px; font-size: 0.4375rem; text-align: center; }
.people-designation-picker { margin: 0; border: 1px solid #dfe2df; border-radius: 11px; padding: 13px; display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 7px; }
.people-designation-picker legend { color: #5c666b; padding: 0 6px; font-size: 0.5rem; font-weight: 900; }
.people-designation-picker label { border: 1px solid #e0e3e0; border-radius: 7px; padding: 8px; display: flex; align-items: center; gap: 7px; color: #596469; font-size: 0.5rem; }
.people-modal { max-width: 720px; }
.modal-intro { margin: 0; color: #737d82; font-size: 0.625rem; line-height: 1.55; }
.offboarding-warning { border: 1px solid #d6aaa5; border-radius: 11px; background: #fff5f3; padding: 13px; display: flex; gap: 11px; }
.offboarding-warning > span { width: 32px; height: 32px; flex: 0 0 auto; border-radius: 50%; background: var(--orange); color: #fff; display: grid; place-items: center; font-weight: 900; }
.offboarding-warning strong { color: #762820; font-size: 0.625rem; }
.offboarding-warning p { margin: 4px 0 0; color: #805550; font-size: 0.5rem; line-height: 1.45; }
.people-loading { min-height: 300px; display: grid; place-items: center; color: #737d82; font-size: 0.6875rem; font-weight: 800; }

.native-source-only { border-radius: 6px; background: #eef2ef; color: #4d6257 !important; padding: 6px 8px; font-weight: 900; }
.onboarding-document-center { overflow: hidden; border: 1px solid #dce1dd; border-radius: 15px; background: #fff; box-shadow: 0 9px 24px rgba(30,40,42,.055); }
.onboarding-document-center > header { min-height: 82px; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 17px 20px; border-bottom: 1px solid #e5e8e5; }
.onboarding-document-center > header h2 { margin: 3px 0; color: #2d3538; font-size: 1.25rem; }
.onboarding-document-center > header span { color: #788286; font-size: 0.5625rem; }
.onboarding-document-center > header > b { border-radius: 999px; background: #2e3436; color: #fff; padding: 8px 11px; font-size: 0.5rem; }
.onboarding-guided-path{display:grid;gap:14px;padding:18px 20px;border-bottom:1px solid #e5e8e5;background:linear-gradient(135deg,#fbfcfa,#f4f8f5)}
.onboarding-guided-steps{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;align-items:center;gap:12px}.onboarding-guided-steps>span{display:grid;grid-template-columns:30px 1fr;column-gap:9px;align-items:center;padding:10px;border:1px solid #dfe4df;border-radius:10px;background:#fff}.onboarding-guided-steps>span>b{grid-row:1/3;width:30px;height:30px;display:grid;place-items:center;border-radius:50%;background:#e7ebe8;color:#5e696d;font-size:0.625rem}.onboarding-guided-steps>span.current{border-color:#c9968e;background:#fff9f7}.onboarding-guided-steps>span.current>b{background:#843129;color:#fff}.onboarding-guided-steps strong{font-size:0.5625rem}.onboarding-guided-steps small{color:#7a8589;font-size:0.46875rem}.onboarding-guided-steps>i{color:#9ba4a0;font-size:0.8125rem;font-style:normal}
.onboarding-next-action{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:18px;border-radius:13px;background:#283033;color:#fff;box-shadow:0 8px 20px rgba(28,38,40,.13)}.onboarding-next-action>div{display:grid;gap:4px}.onboarding-next-action small{color:#f0b09f;font-size:0.4375rem;font-weight:950;letter-spacing:.08em}.onboarding-next-action strong{font-size:1.0625rem}.onboarding-next-action span{color:#d3d9d6;font-size:0.5625rem}.onboarding-next-action>button{white-space:nowrap}.onboarding-next-action>b{width:38px;height:38px;display:grid;place-items:center;border-radius:50%;background:#2f754f;font-size:1.125rem}.onboarding-next-action.complete{background:#244c39}
.onboarding-simple-progress{position:relative;height:8px;margin-top:3px;border-radius:999px;background:#dfe5e0}.onboarding-simple-progress>span{position:absolute;inset:0 auto 0 0;border-radius:999px;background:#2b7652}.onboarding-simple-progress>small{position:absolute;top:13px;left:0;color:#727d80;font-size:0.46875rem;font-weight:850}
.onboarding-document-list-toggle{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:22px 20px 12px}.onboarding-document-list-toggle>div{display:grid;gap:3px}.onboarding-document-list-toggle strong{font-size:0.6875rem}.onboarding-document-list-toggle span{color:#778185;font-size:0.5rem}
.onboarding-admin-controls{margin:4px 16px 16px;border:1px solid #dfe3df;border-radius:10px;background:#fafbf9;overflow:hidden}.onboarding-admin-controls>summary{padding:13px 15px;color:#596367;font-size:0.5rem;font-weight:950;cursor:pointer}.onboarding-admin-controls .onboarding-document-policy,.onboarding-admin-controls .onboarding-provider-boundary,.onboarding-admin-controls .onboarding-live-roles{border-top:1px solid #dfe3df}.onboarding-employee-links{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:3px 20px 17px;padding:11px 13px;border:1px solid #dfe3df;border-radius:9px;background:#fafbf9}.onboarding-employee-links span{color:#697478;font-size:0.5rem}.onboarding-employee-links a{color:#843129;font-size:0.5rem;font-weight:900;text-decoration:none}
.onboarding-document-policy { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap: 1px; background: #dde2de; }
.onboarding-document-policy span { min-height: 55px; display: grid; align-content: center; gap: 3px; padding: 10px 14px; background: #f7f9f7; color: #65716d; font-size: 0.5rem; }
.onboarding-document-policy b { color: #843129; font-size: 0.4375rem; letter-spacing: .06em; }
.onboarding-document-summary { display: grid; grid-template-columns: repeat(3,1fr); gap: 9px; padding: 13px 16px 0; }
.onboarding-document-summary article { min-height: 62px; display: flex; align-items: center; gap: 9px; padding: 10px 13px; border: 1px solid #dfe3df; border-radius: 9px; background: #fafbf9; }
.onboarding-document-summary article.held { border-color: #dfbd82; background: #fff9ed; }
.onboarding-document-summary strong { color: #333b3e; font-size: 1.4375rem; }
.onboarding-document-summary span { color: #707b7f; font-size: 0.5rem; font-weight: 900; text-transform: uppercase; }
.onboarding-document-center > .accounting-notice { margin: 13px 16px 0; }
.onboarding-document-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 11px; padding: 14px 16px 17px; }
.onboarding-document-card { min-width: 0; display: grid; align-content: start; gap: 8px; padding: 15px; border: 1px solid #dfe3df; border-radius: 11px; background: #fff; }
.onboarding-document-card.held { border-color: #e2c995; background: #fffdf7; }
.onboarding-document-card-top { display: flex; align-items: center; justify-content: space-between; gap: 9px; }
.onboarding-document-card-top > span { color: #843129; font-size: 0.4375rem; font-weight: 950; letter-spacing: .08em; text-transform: uppercase; }
.document-state { border-radius: 999px; background: #eef1ef; color: #5c6964; padding: 5px 7px; font-size: 0.4375rem; }
.document-state.complete { background: #e1f1e8; color: #186546; }
.document-state.employer-review-required, .document-state.employee-signed, .document-state.draft { background: #fff0d9; color: #7e5505; }
.document-state.held { background: #f6e5e1; color: #873128; }
.onboarding-document-card h3 { margin: 0; color: #30383b; font-size: 0.8125rem; }
.onboarding-document-card > p { min-height: 35px; margin: 0; color: #6e797d; font-size: 0.53125rem; line-height: 1.5; }
.onboarding-document-card dl { margin: 0; display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 7px; }
.onboarding-document-card dl > div { min-width: 0; display: grid; gap: 2px; padding: 7px 8px; border-radius: 7px; background: #f7f8f6; }
.onboarding-document-card dt { color: #8a9290; font-size: 0.40625rem; font-weight: 900; }
.onboarding-document-card dd { overflow: hidden; margin: 0; color: #495357; font-size: 0.5rem; font-weight: 800; text-overflow: ellipsis; }
.document-review-evidence { color: #2b7255; font-size: 0.46875rem; }
.onboarding-document-actions { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: auto; padding-top: 4px; }
.onboarding-document-actions a, .onboarding-document-actions > span { color: #843129; font-size: 0.5rem; font-weight: 900; text-decoration: none; }
.onboarding-document-actions button { border: 0; border-radius: 7px; background: #843129; color: #fff; padding: 8px 9px; font-size: 0.5rem; font-weight: 900; }
.onboarding-document-actions button.held-action { background: #8a630f; }
.onboarding-document-actions button:disabled { background: #c5cbc7; cursor: not-allowed; }
