@media print {
  body * {
    visibility: hidden !important;
  }
  .pdf-preview,
  .pdf-preview *,
  .formal-change-order-preview,
  .formal-change-order-preview *,
  .schedule-print-sheet,
  .schedule-print-sheet *,
  .owner-invoice-preview,
  .owner-invoice-preview * {
    visibility: visible !important;
  }
  .schedule-print-sheet {
    page: mefford-schedule;
    width: 100%;
    display: block;
    position: absolute;
    inset: 0;
    background: #fff;
    color: #202427;
    font-family: Arial, sans-serif;
  }
  .schedule-print-sheet > header {
    min-height: 0.82in;
    border-bottom: 4px solid #922e26;
    padding: 0 0 0.16in;
    display: grid;
    grid-template-columns: 0.72in 1fr auto;
    gap: 0.14in;
    align-items: center;
  }
  .schedule-print-sheet header img {
    width: 0.63in;
    height: 0.63in;
    object-fit: contain;
  }
  .schedule-print-sheet header p {
    margin: 0;
    color: #922e26;
    font-size: 8pt;
    font-weight: 800;
    letter-spacing: 0.08em;
  }
  .schedule-print-sheet header h1 {
    margin: 2px 0;
    font-size: 19pt;
  }
  .schedule-print-sheet header span {
    color: #60676b;
    font-size: 8pt;
  }
  .schedule-print-sheet header aside {
    border: 1px solid #c9cdca;
    padding: 0.1in 0.13in;
    display: grid;
    gap: 3px;
  }
  .schedule-print-sheet header aside strong {
    color: #922e26;
    font-size: 7pt;
    text-transform: uppercase;
  }
  .schedule-print-project {
    padding: 0.12in 0;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.06in 0.18in;
  }
  .schedule-print-project span {
    display: flex;
    gap: 6px;
    font-size: 7.5pt;
  }
  .schedule-print-project b {
    color: #922e26;
  }
  .schedule-print-sheet table {
    width: 100%;
    border-collapse: collapse;
    font-size: 7.2pt;
  }
  .schedule-print-sheet th {
    background: #292e31;
    color: #fff;
    padding: 6px;
    text-align: left;
  }
  .schedule-print-sheet td {
    border-bottom: 1px solid #d9dcda;
    padding: 5px 6px;
  }
  .schedule-print-sheet tbody tr:nth-child(even) {
    background: #f3f4f2;
  }
  .schedule-print-sheet > footer {
    margin-top: 0.12in;
    border-top: 1px solid #bfc4c1;
    padding-top: 0.07in;
    display: flex;
    justify-content: space-between;
    color: #6d7478;
    font-size: 7pt;
  }
  .formal-change-order-preview {
    width: 8.5in;
    max-height: none;
    position: absolute;
    inset: 0;
    overflow: visible;
    padding: 0.45in 0.55in;
    border-radius: 0;
    box-shadow: none;
  }
  .formal-preview-actions,
  .formal-execution-panel {
    display: none;
  }
  .pdf-preview {
    width: 100%;
    max-height: none;
    position: absolute;
    inset: 0;
    overflow: visible;
    border-radius: 0;
    background: white;
    box-shadow: none;
  }
  .pdf-toolbar {
    display: none;
  }
  .pdf-page {
    width: 100%;
    min-height: 0;
    margin: 0;
    padding: 0.55in;
    box-shadow: none;
  }
  .contract-preview-nav {
    display: none;
  }
  .contract-pages {
    padding: 0;
    background: white;
  }
  .contract-pages > div {
    display: contents;
  }
  .contract-sheet {
    width: 8.5in;
    min-height: 11in;
    margin: 0;
    padding: 0.42in 0.5in 0.38in;
    box-shadow: none;
    break-after: page;
    page-break-after: always;
  }
  .contract-sheet:last-child {
    break-after: auto;
    page-break-after: auto;
  }
  .digital-signature-line {
    pointer-events: none;
  }
  .digital-signature-line > i {
    display: none;
  }
  .digital-signature-line > b {
    background: transparent !important;
    outline: 0 !important;
  }
}

