html { scroll-behavior: smooth; }
body { -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility; }
button, input, select, textarea { transition: border-color .16s ease, box-shadow .16s ease, background-color .16s ease, color .16s ease, transform .16s ease; }
button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, a:focus-visible, summary:focus-visible {
  outline: 3px solid rgba(155, 53, 45, .2);
  outline-offset: 2px;
}
::selection { background: #ead0cc; color: #55201b; }
* { scrollbar-width: thin; scrollbar-color: #b9c5bd transparent; }

.operations-app-mode {
  background:
    radial-gradient(circle at 74% -12%, rgba(155, 53, 45, .1), transparent 31%),
    linear-gradient(180deg, #f6f8f5 0, #eef3ef 100%);
}
.operations-app-mode .sidebar {
  width: 264px;
  flex-basis: 264px;
  background:
    radial-gradient(circle at 18% 0, rgba(155, 53, 45, .23), transparent 28%),
    linear-gradient(180deg, #18231f 0, #101713 100%);
  border-right: 1px solid rgba(255, 255, 255, .06);
  box-shadow: 13px 0 36px rgba(22, 34, 28, .08);
}
.operations-app-mode .brand { height: 88px; padding: 0 22px; border-bottom-color: rgba(255, 255, 255, .09); }
.operations-app-mode .brand-mark img { filter: drop-shadow(0 5px 10px rgba(0, 0, 0, .2)); }
.operations-app-mode .brand strong { font-size: 1.125rem; letter-spacing: .11em; }
.operations-app-mode .brand span { color: #a7b6ae; font-size: 0.5625rem; }
.operations-app-mode .main-nav { padding: 20px 12px 28px; gap: 5px; }
.operations-app-mode .nav-label { margin: 8px 10px 7px; color: #8ea097; font-size: 0.625rem; letter-spacing: .16em; }
.operations-app-mode .nav-item,
.operations-app-mode .nav-folder {
  min-height: 46px;
  padding: 0 11px;
  border-radius: 12px;
  color: #b7c4bd;
  font-size: 0.8125rem;
}
.operations-app-mode .nav-item:hover,
.operations-app-mode .nav-folder:hover { background: rgba(255, 255, 255, .075); color: #fff; transform: translateX(2px); }
.operations-app-mode .nav-item.active,
.operations-app-mode .nav-folder.active {
  background: linear-gradient(90deg, rgba(155, 53, 45, .5), rgba(255, 255, 255, .075));
  color: #fff;
  box-shadow: inset 3px 0 #dc8177, 0 8px 20px rgba(0, 0, 0, .1);
}
.operations-app-mode .nav-icon {
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  border: 1px solid rgba(255, 255, 255, .06);
  border-radius: 9px;
  background: rgba(255, 255, 255, .08);
  color: #e7efea;
  font-size: 0.9375rem;
  line-height: 1;
  opacity: 1;
}
.operations-app-mode .nav-folder-items { margin-left: 26px; padding-left: 11px; border-left-color: rgba(255, 255, 255, .13); }
.operations-app-mode .nav-subitem { min-height: 41px; grid-template-columns: 22px minmax(0, 1fr); border-radius: 9px; color: #a6b3ac; }
.operations-app-mode .nav-subitem > span { color: #9aaca2; font-size: 0.8125rem; }
.operations-app-mode .nav-subitem b { font-size: 0.75rem; }
.operations-app-mode .nav-subitem:hover,
.operations-app-mode .nav-subitem.active { background: rgba(255, 255, 255, .075); color: #fff; }
.operations-app-mode .sidebar-bottom { padding: 12px; border-top-color: rgba(255, 255, 255, .09); background: rgba(0, 0, 0, .12); }
.operations-app-mode .user-card { padding: 13px 9px 6px; }
.operations-app-mode .avatar { width: 40px; height: 40px; background: #853229; color: #fff; font-size: 0.75rem; }
.operations-app-mode .user-card strong { font-size: 0.75rem; }
.operations-app-mode .user-card span { color: #9aa9a1; font-size: 0.625rem; }

.operations-app-mode .topbar {
  height: 88px;
  padding: 0 32px;
  background: rgba(255, 255, 255, .91);
  border-bottom-color: rgba(207, 217, 210, .9);
  box-shadow: 0 7px 25px rgba(30, 43, 35, .045);
  backdrop-filter: blur(18px) saturate(125%);
}
.operations-app-mode .eyebrow { color: #7b8881; font-size: 0.625rem; letter-spacing: .12em; }
.operations-app-mode .project-badge { width: 39px; height: 39px; border-radius: 12px; background: linear-gradient(145deg, #f7e4e0, #f2d5d0); font-size: 0.6875rem; }
.operations-app-mode .project-switcher strong { color: #202a26; font-size: 0.9375rem; }
.operations-app-mode .project-switcher small { color: #738079; font-size: 0.65625rem; }
.operations-app-mode .project-menu { width: 340px; top: 64px; border-radius: 15px; box-shadow: var(--shadow-md); }
.operations-app-mode .topbar-actions { gap: 9px; }
.operations-app-mode .sync-state { min-height: 38px; display: inline-flex; align-items: center; padding: 0 11px; border: 1px solid #d9e2dc; border-radius: 999px; background: #f8faf8; color: #5e6b64; font-size: 0.625rem; }
.operations-app-mode .icon-button { width: 42px; height: 42px; border-radius: 12px; }
.operations-app-mode .primary-action {
  min-height: 42px;
  height: auto;
  border-radius: 11px;
  padding: 0 17px;
  background: linear-gradient(135deg, #a63d34, #842b24);
  font-size: 0.75rem;
  box-shadow: 0 7px 16px rgba(132, 43, 36, .19);
}
.operations-app-mode .primary-action:hover:not(:disabled) { transform: translateY(-1px); box-shadow: 0 10px 20px rgba(132, 43, 36, .23); }
.operations-app-mode .secondary-action,
.operations-app-mode .danger-action { min-height: 42px; height: auto; border-radius: 10px; padding: 0 15px; font-size: 0.6875rem; font-weight: 800; }

.operations-app-mode .content { max-width: 1520px; padding: 28px 38px 54px; }
.operations-app-mode .content label { font-size: 0.6875rem; }
.operations-app-mode .content small { font-size: 0.625rem; line-height: 1.4; }
.operations-app-mode .content :where(td, th) { font-size: 0.65625rem; }
.experience-guide {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) minmax(220px, .37fr);
  align-items: center;
  gap: 15px;
  margin: 0 0 18px;
  padding: 14px 17px;
  border: 1px solid #dce4de;
  border-left: 4px solid var(--orange);
  border-radius: 16px;
  background: rgba(255, 255, 255, .9);
  box-shadow: var(--shadow-sm);
  backdrop-filter: blur(12px);
}
.experience-guide-icon { width: 44px; height: 44px; display: grid; place-items: center; border-radius: 13px; background: linear-gradient(145deg, #f8e8e5, #f3d9d5); color: #8e3028; font-size: 1.25rem; font-weight: 900; }
.experience-guide-copy { min-width: 0; display: grid; gap: 2px; }
.experience-guide-copy small,
.experience-guide-next small { color: #8b3932; font-size: 0.5625rem; font-weight: 950; letter-spacing: .1em; }
.experience-guide-copy strong { color: #24302b; font-size: 1rem; letter-spacing: -.01em; }
.experience-guide-copy p { margin: 0; color: #6b7771; font-size: 0.78125rem; line-height: 1.45; }
.experience-guide-next { align-self: stretch; display: grid; align-content: center; gap: 4px; padding-left: 16px; border-left: 1px solid #e0e6e2; }
.experience-guide-next strong { color: #2a3932; font-size: 0.75rem; line-height: 1.4; }

.operations-app-mode .module-workspace { min-height: calc(100vh - 174px); }
.operations-app-mode .workspace-heading {
  align-items: center;
  margin-bottom: 18px;
  padding: 24px 27px;
  border: 1px solid #dfe6e1;
  border-radius: 19px;
  background: linear-gradient(135deg, rgba(255, 255, 255, .98), rgba(248, 250, 248, .95));
  box-shadow: var(--shadow-sm);
}
.operations-app-mode .workspace-heading h1 { margin: 6px 0 6px; color: #1b2822; font-size: clamp(28px, 3vw, 38px); letter-spacing: -.035em; }
.operations-app-mode .workspace-heading p:last-child { max-width: 790px; color: #69766f; font-size: 0.84375rem; line-height: 1.55; }
.operations-app-mode .workspace-heading-actions { gap: 9px; }
.operations-app-mode .panel,
.operations-app-mode .records-panel {
  border-color: #dce4de;
  border-radius: 16px;
  box-shadow: var(--shadow-sm);
}
.operations-app-mode .panel-heading { min-height: 62px; height: auto; padding: 12px 19px; }
.operations-app-mode .panel-heading h2 { color: #28342f; font-size: 0.9375rem; }
.operations-app-mode .panel-heading button { min-height: 36px; padding: 0 9px; font-size: 0.6875rem; }
.operations-app-mode .heading-mark { width: 5px; height: 23px; border-radius: 999px; }
.operations-app-mode .module-summary { gap: 12px; margin-bottom: 16px; }
.operations-app-mode .module-summary article { min-height: 100px; align-items: center; padding: 18px 20px; border-color: #dce4de; border-radius: 15px; box-shadow: var(--shadow-sm); }
.operations-app-mode .module-summary strong { color: #1f2b26; font-size: 1.75rem; letter-spacing: -.035em; }
.operations-app-mode .module-summary span { color: #738078; font-size: 0.6875rem; }
.operations-app-mode .records-tools { min-height: 65px; height: auto; padding: 11px 16px; }
.operations-app-mode .records-tools label { height: 43px; border-radius: 11px; background: #fafcfb; }
.operations-app-mode .record-head { min-height: 41px; font-size: 0.625rem; }
.operations-app-mode .record-row { min-height: 70px; padding-block: 11px; font-size: 0.71875rem; }
.operations-app-mode .record-row:hover { background: #f8faf8; }
.operations-app-mode .record-title strong { font-size: 0.8125rem; }
.operations-app-mode .record-title small { color: #7d8982; font-size: 0.625rem; }
.operations-app-mode .record-id { font-size: 0.6875rem; }
.operations-app-mode .status-badge { min-height: 27px; display: inline-grid; place-items: center; padding: 5px 9px; border-radius: 999px; font-size: 0.59375rem; }
.operations-app-mode .empty-state,
.operations-app-mode .empty-module-state,
.operations-app-mode .record-empty { min-height: 150px; display: grid; place-content: center; padding: 28px; border-radius: 13px; background: radial-gradient(circle at 50% 0, #fff, #f6f8f6); color: #718078; font-size: 0.75rem; line-height: 1.55; text-align: center; }

.operations-app-mode .module-grid { gap: 12px; }
.operations-app-mode .module-card { min-height: 84px; padding: 14px; border-radius: 14px; box-shadow: var(--shadow-sm); }
.operations-app-mode .module-icon { width: 44px; height: 44px; flex-basis: 44px; border-radius: 12px; font-size: 0.6875rem; }
.operations-app-mode .module-card strong { font-size: 0.78125rem; }
.operations-app-mode .module-card small { color: #7c8982; font-size: 0.625rem; }
.operations-app-mode .attention-item { min-height: 74px; padding: 12px 18px; }
.operations-app-mode .type-badge { min-width: 68px; height: 27px; border-radius: 7px; font-size: 0.5625rem; }
.operations-app-mode .attention-copy strong { font-size: 0.75rem; }
.operations-app-mode .attention-copy small,
.operations-app-mode .due { font-size: 0.625rem; }
.operations-app-mode .section-title h2 { font-size: 1.125rem; }
.operations-app-mode .section-title p,
.operations-app-mode .section-title button { font-size: 0.6875rem; }

.operations-app-mode .field-grid { gap: 14px; }
.operations-app-mode .field-label { gap: 7px; margin-bottom: 15px; color: #56655d; font-size: 0.71875rem; }
.operations-app-mode .field-label input,
.operations-app-mode .field-label select,
.operations-app-mode .field-label textarea {
  min-height: 44px;
  border-color: #ccd7d0;
  border-radius: 10px;
  padding: 10px 12px;
  background: #fff;
  font-size: 0.8125rem;
}
.operations-app-mode .field-label textarea { min-height: 96px; }
.operations-app-mode .field-label input:hover,
.operations-app-mode .field-label select:hover,
.operations-app-mode .field-label textarea:hover { border-color: #aebeb4; }
.operations-app-mode .field-label input:focus,
.operations-app-mode .field-label select:focus,
.operations-app-mode .field-label textarea:focus { border-color: #9b352d; box-shadow: 0 0 0 4px rgba(155, 53, 45, .1); }
.operations-app-mode .form-rule,
.operations-app-mode .permission-note,
.operations-app-mode .inline-success,
.operations-app-mode .inline-error,
.operations-app-mode .accounting-notice { border-radius: 12px; padding: 12px 14px; font-size: 0.71875rem; line-height: 1.55; }
.operations-app-mode .check-grid { gap: 9px; }
.operations-app-mode .check-grid label { min-height: 42px; border-radius: 9px; padding: 8px 10px; font-size: 0.6875rem; }

.modal-layer { background: rgba(20, 29, 25, .64); backdrop-filter: blur(6px); }
.operations-app-mode .record-modal { border: 1px solid rgba(255, 255, 255, .55); border-radius: 21px; padding: 24px; box-shadow: 0 28px 80px rgba(16, 28, 22, .3); }
.operations-app-mode .modal-heading { margin-bottom: 22px; padding-bottom: 16px; border-bottom: 1px solid #e4e9e5; }
.operations-app-mode .modal-heading h2 { color: #202c27; font-size: 1.5625rem; letter-spacing: -.025em; }
.operations-app-mode .modal-heading > button { width: 40px; height: 40px; border-radius: 50%; background: #f7f9f7; }
.operations-app-mode .modal-actions { position: sticky; bottom: -24px; z-index: 2; margin: 22px -24px -24px; padding: 15px 24px; border-top: 1px solid #e2e8e3; background: rgba(255, 255, 255, .95); backdrop-filter: blur(10px); }

.operations-app-mode :where(
  .executive-hero,
  .owner-contract-hero,
  .vendor-admin-hero,
  .quality-hero,
  .review-hero,
  .selection-hero,
  .safety-command-hero,
  .closeout-hero,
  .integration-hero,
  .financial-report-hero,
  .sales-dashboard-hero,
  .people-hero,
  .onboarding-admin-hero,
  .design-hero,
  .project-health-hero
) { border-radius: 22px; box-shadow: var(--shadow-md); }
.operations-app-mode :where(
  .executive-metrics,
  .sales-dashboard-metrics,
  .quality-metrics,
  .review-metrics,
  .selection-summary-grid,
  .safety-command-metrics,
  .closeout-summary,
  .vendor-admin-summary,
  .people-summary
) article { border-radius: 16px; box-shadow: var(--shadow-sm); }
.operations-app-mode :where(
  .quality-tabs,
  .selection-tabs,
  .safety-command-tabs,
  .closeout-tabs,
  .vendor-tabs,
  .people-tabs,
  .sales-tabs,
  .accounting-tabs
) button { min-height: 42px; font-size: 0.65625rem; }

/* Accounting intentionally remains compact, aligned, and number-first. */
.accounting-app-mode { --canvas: #edf1ee; --font-xxs: 0.5rem; --font-xs: 0.5625rem; background: #edf1ee; }
.accounting-app-mode .sidebar { width: 238px; flex-basis: 238px; }
.accounting-app-mode .nav-folder-items { margin-left: 18px; padding-left: 7px; }
.accounting-app-mode .topbar { background: rgba(255, 255, 255, .96); box-shadow: 0 3px 12px rgba(26, 36, 31, .04); }
.accounting-app-mode .experience-guide { grid-template-columns: 34px minmax(0, 1fr) minmax(190px, .32fr); gap: 11px; margin-bottom: 12px; padding: 10px 13px; border-left-width: 3px; border-radius: 8px; box-shadow: none; }
.accounting-app-mode .experience-guide-icon { width: 34px; height: 34px; border-radius: 7px; font-size: 0.9375rem; }
.accounting-app-mode .experience-guide-copy small,
.accounting-app-mode .experience-guide-next small { font-size: 0.46875rem; }
.accounting-app-mode .experience-guide-copy strong { font-size: 0.8125rem; }
.accounting-app-mode .experience-guide-copy p,
.accounting-app-mode .experience-guide-next strong { font-size: 0.625rem; }
.accounting-app-mode .workspace-heading { padding: 18px 20px; border-radius: 9px; background: #fff; }
.accounting-app-mode input,
.accounting-app-mode select,
.accounting-app-mode textarea { font-variant-numeric: tabular-nums; }

@media (max-width: 1180px) {
  .operations-app-mode .sidebar { width: 250px; flex-basis: 250px; }
  .operations-app-mode .content { padding-inline: 24px; }
  .operations-app-mode .sync-state { display: none; }
  .experience-guide { grid-template-columns: auto minmax(0, 1fr); }
  .experience-guide-next { grid-column: 2; padding: 10px 0 0; border-top: 1px solid #e0e6e2; border-left: 0; }
}

@media (max-width: 900px) {
  .operations-app-mode .sidebar { width: min(300px, 86vw); }
  .operations-app-mode .topbar { height: 76px; padding: 0 17px; }
  .operations-app-mode .content { padding: 20px 18px 100px; }
  .operations-app-mode .workspace-heading { align-items: stretch; padding: 21px; }
  .operations-app-mode .topbar .primary-action { display: none; }
}

@media (max-width: 680px) {
  .operations-app-mode .content { padding: 16px 13px 96px; }
  .operations-app-mode .project-badge { width: 34px; height: 34px; }
  .operations-app-mode .project-switcher strong { font-size: 0.8125rem; }
  .operations-app-mode .project-switcher small { max-width: 210px; overflow: hidden; font-size: 0.5625rem; text-overflow: ellipsis; white-space: nowrap; }
  .experience-guide { grid-template-columns: 38px minmax(0, 1fr); gap: 10px; padding: 12px; border-radius: 13px; }
  .experience-guide-icon { width: 38px; height: 38px; border-radius: 10px; font-size: 1.0625rem; }
  .experience-guide-copy strong { font-size: 0.875rem; }
  .experience-guide-copy p { font-size: 0.6875rem; }
  .experience-guide-next { grid-column: 1 / -1; padding-top: 9px; }
  .operations-app-mode .workspace-heading { display: grid; gap: 17px; padding: 19px 17px; border-radius: 16px; }
  .operations-app-mode .workspace-heading h1 { font-size: 1.6875rem; }
  .operations-app-mode .workspace-heading p:last-child { font-size: 0.75rem; }
  .operations-app-mode .workspace-heading-actions { display: grid; grid-template-columns: 1fr; }
  .operations-app-mode .workspace-heading-actions > * { width: 100%; }
  .operations-app-mode .module-summary { grid-template-columns: 1fr; }
  .operations-app-mode .module-summary article { min-height: 78px; }
  .operations-app-mode .field-grid { grid-template-columns: 1fr; }
  .operations-app-mode .record-modal { width: 100%; max-height: calc(100vh - 8px); align-self: end; border-radius: 22px 22px 0 0; padding: 20px; }
  .operations-app-mode .modal-actions { bottom: -20px; margin: 20px -20px -20px; padding: 13px 20px; }
  .operations-app-mode .modal-actions > * { min-width: 0; flex: 1; }
  .accounting-app-mode .experience-guide { grid-template-columns: 32px minmax(0, 1fr); }
  .accounting-app-mode .experience-guide-next { grid-column: 1 / -1; }
}
