.proposal-visual-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  border: 1px solid #d4dad6;
  border-left: 5px solid #a33e35;
  background: #f7f6f1;
  padding: 16px 18px;
}
.proposal-visual-toolbar > div { display: grid; gap: 4px; }
.proposal-visual-toolbar strong { color: #202a25; font-size: 0.8125rem; }
.proposal-visual-toolbar span { color: #68746e; font-size: 0.625rem; }
.proposal-visual-toolbar > label { display: inline-flex; align-items: center; justify-content: center; min-height: 42px; cursor: pointer; white-space: nowrap; }
.proposal-visual-toolbar input[type="file"] { display: none; }
.proposal-visual-toolbar > .proposal-visual-actions { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 8px; }
.proposal-visual-actions > label { display: inline-flex; align-items: center; justify-content: center; min-height: 42px; box-sizing: border-box; cursor: pointer; white-space: nowrap; }
.proposal-visual-section { display: grid; gap: 12px; }
.proposal-visual-section > header { display: flex; align-items: end; justify-content: space-between; gap: 15px; padding-bottom: 10px; border-bottom: 1px solid #dde2de; }
.proposal-visual-section > header > div { display: grid; gap: 3px; }
.proposal-visual-section > header span,
.proposal-source-library > section > header span { color: #a33e35; font-size: 0.5rem; font-weight: 950; letter-spacing: .12em; }
.proposal-visual-section > header strong,
.proposal-source-library > section > header strong { color: #202a25; font-size: 0.875rem; }
.proposal-visual-section > header small { color: #6c7871; font-size: 0.5625rem; }
.proposal-selected-visuals { display: grid; gap: 10px; }
.proposal-selected-visuals > article { display: grid; grid-template-columns: 112px minmax(0,1fr); gap: 14px; border: 1px solid #d5ddd7; background: #fff; padding: 12px; }
.proposal-selected-visuals > article.excluded { opacity: .55; background: #f0f1ee; }
.proposal-visual-thumb { display: grid; place-items: center; min-height: 104px; overflow: hidden; background: #1b2420; color: #fff; }
.proposal-visual-thumb img { width: 100%; height: 104px; object-fit: cover; }
.proposal-visual-thumb span { color: #d98278; font-size: 1rem; font-weight: 950; letter-spacing: .12em; }
.proposal-visual-fields { display: grid; gap: 10px; min-width: 0; }
.proposal-visual-fields > header { display: flex; align-items: start; justify-content: space-between; gap: 12px; }
.proposal-visual-fields > header > div { display: grid; gap: 3px; min-width: 0; }
.proposal-visual-fields > header span { color: #a33e35; font-size: .5rem; font-weight: 950; }
.proposal-visual-fields > header strong { overflow: hidden; color: #25302a; font-size: .75rem; text-overflow: ellipsis; white-space: nowrap; }
.proposal-visual-fields > header label { display: flex; align-items: center; gap: 6px; color: #445149; font-size: .5625rem; font-weight: 850; }
.proposal-visual-controls { display: grid; grid-template-columns: 170px 120px minmax(190px,1fr); gap: 9px; }
.proposal-visual-controls > label { display: grid; gap: 5px; min-width: 0; }
.proposal-visual-controls > label > span { color: #68746e; font-size: .5rem; font-weight: 850; }
.proposal-visual-controls input,
.proposal-visual-controls select { width: 100%; min-height: 38px; border: 1px solid #cbd3ce; background: #fafaf7; padding: 0 10px; color: #202a25; font-size: .625rem; }
.proposal-visual-fields > footer { display: grid; grid-template-columns: auto auto 1fr auto; gap: 7px; }
.proposal-visual-fields > footer button,
.proposal-source-library article > button { min-height: 32px; border: 1px solid #bdc9c1; background: #fff; color: #325a47; padding: 0 10px; font-size: .5rem; font-weight: 900; }
.proposal-visual-fields > footer button:last-child { border-color: #d7b6b1; color: #93352d; }
.proposal-visual-fields > footer button:disabled,
.proposal-source-library article > button:disabled { opacity: .45; cursor: default; }
.proposal-visual-empty { display: grid; gap: 5px; border: 1px dashed #cbd4ce; background: #fafaf7; padding: 22px; text-align: center; }
.proposal-visual-empty strong { font-size: .75rem; }
.proposal-visual-empty span { color: #6c7871; font-size: .625rem; }
.proposal-source-library { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.proposal-source-library > section { display: grid; align-content: start; gap: 10px; border: 1px solid #d6ddd8; background: #f7f7f3; padding: 14px; }
.proposal-source-library > section > header { display: grid; gap: 3px; padding-bottom: 9px; border-bottom: 1px solid #d9dfdb; }
.proposal-source-library > section > div { display: grid; gap: 7px; }
.proposal-source-library article { display: grid; grid-template-columns: 54px minmax(0,1fr) auto; align-items: center; gap: 9px; min-width: 0; background: #fff; padding: 8px; }
.proposal-source-library article > img,
.proposal-source-pdf { width: 54px; height: 46px; object-fit: cover; }
.proposal-source-pdf { display: grid; place-items: center; background: #202925; color: #d88075; font-size: .625rem; font-weight: 950; }
.proposal-source-library article > div { display: grid; gap: 3px; min-width: 0; }
.proposal-source-library article strong { overflow: hidden; font-size: .625rem; text-overflow: ellipsis; white-space: nowrap; }
.proposal-source-library article span { color: #6f7b74; font-size: .5rem; }
.proposal-source-library > section > small { color: #6c7871; font-size: .5625rem; line-height: 1.45; }

@media (max-width: 900px) {
  .proposal-visual-controls { grid-template-columns: 1fr 1fr; }
  .proposal-visual-caption { grid-column: 1 / -1; }
  .proposal-source-library { grid-template-columns: 1fr; }
}
@media (max-width: 560px) {
  .proposal-visual-toolbar { align-items: stretch; flex-direction: column; }
  .proposal-visual-toolbar > .proposal-visual-actions { justify-content: stretch; }
  .proposal-visual-actions > label { flex: 1; }
  .proposal-selected-visuals > article { grid-template-columns: 1fr; }
  .proposal-visual-thumb { min-height: 150px; }
  .proposal-visual-thumb img { height: 150px; }
  .proposal-visual-controls { grid-template-columns: 1fr; }
  .proposal-visual-caption { grid-column: auto; }
  .proposal-source-library article { grid-template-columns: 48px minmax(0,1fr); }
  .proposal-source-library article > button { grid-column: 1 / -1; }
}

