.owner-approval-center { min-height: 100%; padding: 24px; background: #f3f5f3; color: #293237; }
.owner-approval-hero { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 22px 24px; border-radius: 13px; background: #252c30; color: white; }
