.owner-approval-hero h1 { margin: 4px 0; font-size: 1.65rem; }
.owner-approval-hero span { color: #c5cccf; font-size: .5625rem; }
.owner-approval-hero > div:last-child { text-align: right; }
.owner-approval-hero > div:last-child strong { display: block; color: white; font-size: 2rem; }
.owner-approval-notice { width: 100%; margin-top: 10px; border: 1px solid #d7aaa5; border-radius: 8px; background: #fff7f5; color: #8e302a; padding: 10px 12px; display: flex; justify-content: space-between; font-weight: 800; }
.owner-approval-metrics { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; margin: 14px 0; }
.owner-approval-metrics button { min-width: 0; border: 1px solid #dce1dd; border-radius: 10px; background: white; padding: 13px; text-align: left; cursor: pointer; }
.owner-approval-metrics span { display: block; color: #788287; font-size: .4375rem; font-weight: 900; letter-spacing: .07em; }
.owner-approval-metrics strong { display: block; margin: 6px 0 3px; font-size: 1.1rem; }
.owner-approval-metrics small { color: #818b90; font-size: .4375rem; }
.owner-approval-tabs { display: flex; gap: 4px; margin-bottom: 10px; }
.owner-approval-tabs button { border: 0; border-radius: 7px; background: transparent; padding: 8px 12px; color: #687279; font-size: .5625rem; font-weight: 850; }
.owner-approval-tabs button.active { background: #252c30; color: white; }
.owner-batch-bar { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 10px; border: 1px solid #c7d9cf; border-radius: 9px; background: #f1f8f5; padding: 11px 14px; }
.owner-batch-bar div { display: flex; flex-direction: column; gap: 2px; }
.owner-batch-bar span { color: #64736b; font-size: .5rem; }
.owner-batch-bar button { border: 0; border-radius: 7px; background: #2e765a; color: white; padding: 9px 13px; font-size: .5rem; font-weight: 900; }
.owner-approval-layout { display: grid; grid-template-columns: minmax(360px, .88fr) minmax(520px, 1.35fr); gap: 12px; align-items: start; }
.owner-approval-queue, .owner-decision-packet, .owner-approval-history { border: 1px solid #d9dfda; border-radius: 11px; background: white; overflow: hidden; }
.owner-approval-queue article { display: grid; grid-template-columns: 26px minmax(0, 1fr) auto; gap: 10px; align-items: start; padding: 12px; border-top: 1px solid #edf0ed; cursor: pointer; }
.owner-approval-queue article:first-child { border-top: 0; }
.owner-approval-queue article.active { background: #fff7f5; box-shadow: inset 3px 0 0 var(--orange); }
.owner-approval-queue input { width: 17px; height: 17px; accent-color: #2e765a; }
.owner-approval-queue article > div { min-width: 0; }
.owner-approval-queue strong { display: block; font-size: .5625rem; }
.owner-approval-queue small { color: #778187; font-size: .4375rem; }
.owner-approval-queue p { margin: 5px 0 0; color: #59656b; font-size: .5rem; line-height: 1.4; }
.owner-approval-queue article > b { font-size: .5625rem; white-space: nowrap; }
.approval-level { display: inline-grid; min-width: 22px; height: 22px; place-items: center; border-radius: 99px; padding: 0 6px; font-size: .4375rem; font-style: normal; font-weight: 950; }
.level-critical { background: #9d2f28; color: white; }.level-exception { background: #f5dfdc; color: #922f29; }.level-material { background: #f5e9cc; color: #725918; }.level-routine { background: #dfeee7; color: #28664e; }
.owner-decision-packet { padding: 17px; }
.owner-decision-packet > header { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; padding-bottom: 14px; border-bottom: 1px solid #e6e9e6; }
