.owner-packet-recommendation span, .owner-decision-packet h3 { margin: 0 0 7px; color: #727d82; font-size: .4375rem; font-weight: 950; letter-spacing: .07em; text-transform: uppercase; }
.owner-packet-recommendation p, .owner-packet-exceptions p { margin: 0; font-size: .5625rem; line-height: 1.5; }
