.owner-packet-columns p { margin: 5px 0; font-size: .5rem; }.owner-packet-columns .passed { color: #2e765a; }.owner-packet-columns .failed { color: #9d2f28; font-weight: 900; }
.owner-packet-exceptions { border-color: #e7c6c2; background: #fffafa; }.owner-packet-exceptions p { margin-top: 5px; color: #8f302a; }.owner-packet-exceptions p.clear { color: #2e765a; }
.owner-packet-evidence button { margin-right: 7px; border: 1px solid #d5dbd7; border-radius: 6px; background: white; padding: 7px 9px; color: #a23932; font-size: .5rem; font-weight: 850; }
.owner-decision-actions { margin-top: 12px; border-top: 1px solid #e1e5e2; padding-top: 12px; }.owner-decision-actions label { display: flex; flex-direction: column; gap: 5px; font-size: .5rem; font-weight: 850; }.owner-decision-actions textarea { resize: vertical; border: 1px solid #d7ddda; border-radius: 7px; padding: 8px; font: inherit; }.owner-decision-actions > div { display: flex; justify-content: flex-end; gap: 8px; margin-top: 8px; }.owner-decision-actions button { border: 1px solid #d2aaa6; border-radius: 7px; background: white; color: #98342d; padding: 9px 12px; font-size: .5rem; font-weight: 900; }.owner-decision-actions button.primary-action { border: 0; background: var(--orange); color: white; }.owner-decision-actions > small { display: block; margin-top: 7px; color: #7a8489; font-size: .4375rem; text-align: right; }
