.small-project-pricing-inputs label { display: grid; align-content: start; gap: 6px; color: #465149; font-size: .6875rem; font-weight: 800; }
.small-project-pricing-inputs label.wide { grid-column: 1 / -1; }
.small-project-pricing-inputs input,
.small-project-pricing-inputs textarea { width: 100%; border: 1px solid #bcc6c0; border-radius: 4px; background: #fff; padding: 10px; color: #1f2924; font: inherit; }
.small-project-pricing-inputs textarea { min-height: 92px; resize: vertical; }
.small-project-percent-input { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 8px; }
.small-project-percent-input b { font-size: .875rem; }
.small-project-no-cap { display: grid; align-content: center; gap: 4px; min-height: 62px; border-left: 3px solid #303a35; background: #f4f5f2; padding: 10px 13px; }
.small-project-no-cap strong { font-size: .75rem; }
.small-project-no-cap span { color: #66716b; font-size: .6875rem; line-height: 1.4; }
.small-project-guaranty { display: flex; align-items: flex-start; gap: 10px; border-top: 1px solid #dfe3e0; padding-top: 14px; color: #27312c; cursor: pointer; }
.small-project-guaranty input { width: 18px; height: 18px; margin: 1px 0 0; accent-color: #303a35; }
.small-project-guaranty span { display: grid; gap: 3px; }
.small-project-guaranty strong { font-size: .75rem; }
.small-project-guaranty small { color: #69746e; font-size: .6875rem; font-weight: 400; line-height: 1.4; }
.small-project-guarantor-name { display: grid; gap: 6px; color: #465149; font-size: .6875rem; font-weight: 800; }
.small-project-guarantor-name input { width: 100%; border: 1px solid #bcc6c0; border-radius: 4px; background: #fff; padding: 10px; color: #1f2924; font: inherit; }
.project-contract-editor-panel .contract-flow-summary { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.project-contract-editor-panel .contract-accounting-strip {
  border: 1px solid #d7ddd9;
  border-left: 5px solid #a33e35;
  border-radius: 5px;
  background: #f7f6f1;
  padding: 17px;
}
.project-contract-editor-panel .contract-editor-shell {
  border-radius: 5px;
  box-shadow: none;
}
.project-contract-editor-panel .contract-source-sync {
  grid-template-columns: minmax(210px, 1fr) auto;
}
.project-contract-editor-panel .contract-field-grid { gap: 15px; padding: 16px 18px 22px; }
.project-contract-editor-panel .contract-contact-routing .contract-field-grid { padding: 0; }
.project-contract-editor-panel .contract-field {
  gap: 8px;
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 0;
}
.project-contract-editor-panel .contract-field.required-open {
  border-left: 3px solid #a33e35;
  background: transparent;
  padding-left: 11px;
}
.project-contract-editor-panel .contract-field > span { color: #3e4a44; font-size: .6875rem; }
.project-contract-editor-panel .contract-field input,
.project-contract-editor-panel .contract-field textarea {
  min-height: 48px;
  border-color: #cbd2cd;
  border-radius: 5px;
  background: #fbfbf8;
  padding: 13px 14px;
  font-size: .75rem;
  line-height: 1.5;
}
.project-contract-editor-panel .contract-field textarea { min-height: 110px; }
.project-contract-editor-panel .contract-field input:focus,
.project-contract-editor-panel .contract-field textarea:focus,
.project-contract-editor-panel .contract-accounting-strip input:focus,
.project-contract-editor-panel .contract-accounting-strip textarea:focus {
  outline: 3px solid #a33e3520;
  border-color: #a33e35;
  background: #fff;
}
.project-contract-editor-panel .owner-portal-control-strip { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.project-contract-editor-panel .owner-negotiation-workspace { border-radius: 5px; }
.project-contract-editor-panel .contract-signature-route { border-radius: 5px; }
.project-contract-live-summary dd { overflow-wrap: anywhere; }
.project-contract-studio-footer {
  grid-template-columns: auto minmax(0, 1fr) repeat(4, auto);
}
.project-contract-studio-footer a,
.contract-studio-footer a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 46px;
  border-radius: 5px;
  padding-inline: 16px;
  font-size: .625rem;
  text-decoration: none;
  white-space: nowrap;
}
@media (max-width: 1280px) {
  .project-contract-studio-body { grid-template-columns: 200px minmax(520px, 1fr); }
  .project-contract-live-summary { display: none; }
  .project-contract-studio-header { grid-template-columns: minmax(240px, 1fr) minmax(340px, 470px) auto; }
}
@media (max-width: 900px) {
  .project-contract-studio-shell { height: 100%; min-height: 0; }
  .project-contract-studio-header { grid-template-columns: 1fr auto; }
  .project-contract-header-summary { grid-column: 1 / -1; grid-row: 2; }
  .project-contract-studio-body { grid-template-columns: 1fr; }
  .project-contract-editor-panel .contract-type-picker,
  .project-contract-editor-panel .contract-flow-summary,
  .project-contract-editor-panel .contract-accounting-strip,
  .project-contract-editor-panel .owner-portal-control-strip { grid-template-columns: 1fr; }
  .small-project-pricing-options,
  .small-project-pricing-inputs { grid-template-columns: 1fr; }
  .small-project-pricing-inputs label.wide { grid-column: auto; }
  .project-contract-studio-footer { grid-template-columns: 1fr 1fr; }
  .project-contract-studio-footer > div,
  .project-contract-studio-footer > span { display: none; }
  .owner-contact-routing-panel > header,
  .owner-contact-subsection { grid-template-columns: 1fr; }
  .owner-contact-routing-panel > header ul { justify-content: flex-start; max-width: none; }
}
@media (max-width: 560px) {
  .project-contract-studio-shell { height: 100%; min-height: 0; border-radius: 0; }
  .project-contract-studio-footer { grid-template-columns: 1fr; }
  .owner-routing-exception-grid { grid-template-columns: 1fr; padding-inline: 14px; }
  .owner-contact-routing-panel > header,
  .owner-contact-subsection,
  .owner-routing-exceptions > summary { padding-inline: 14px; }
}

/* Contract-basis PDFs */
.contract-basis-panel {
  display: grid;
  gap: 16px;
  border: 1px solid #cbd2cd;
  border-left: 5px solid #313a35;
  border-radius: 6px;
  background: #fff;
  padding: 20px;
}
.contract-basis-panel > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 1px solid #dfe3e0;
  padding-bottom: 14px;
}
.contract-basis-panel > header > div { display: grid; gap: 4px; }
.contract-basis-panel > header span {
  color: #8f352e;
  font-size: .5625rem;
  font-weight: 900;
  letter-spacing: .1em;
}
.contract-basis-panel h3 { margin: 0; color: #1e2923; font-size: 1rem; }
.contract-basis-panel > header p,
.contract-basis-panel > footer { margin: 0; color: #68736d; font-size: .6875rem; line-height: 1.5; }
.contract-basis-panel > header > b {
  flex: none;
  border: 1px solid #aeb8b2;
  border-radius: 999px;
  padding: 6px 9px;
  color: #3f4b44;
  font-size: .5625rem;
  letter-spacing: .05em;
}
.contract-basis-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.contract-basis-grid > article {
  display: grid;
  align-content: start;
  gap: 12px;
  border: 1px solid #d7ddd9;
  border-radius: 5px;
  background: #fbfbf9;
  padding: 15px;
}
.contract-basis-grid > article.attached { border-color: #76857c; background: #f7faf8; box-shadow: inset 0 3px #313a35; }
.contract-basis-card-heading { display: grid; grid-template-columns: 32px 1fr auto; align-items: start; gap: 9px; }
.contract-basis-card-heading > span {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border: 1px solid #aeb8b2;
  border-radius: 3px;
  color: #313a35;
  font-size: .625rem;
  font-weight: 900;
}
.contract-basis-card-heading > div { display: grid; gap: 3px; }
.contract-basis-card-heading strong { color: #202b25; font-size: .8125rem; }
.contract-basis-card-heading small { color: #68736d; font-size: .625rem; line-height: 1.4; }
.contract-basis-card-heading i { color: #737e77; font-size: .5rem; font-style: normal; font-weight: 900; letter-spacing: .05em; }
.contract-basis-grid > article.attached .contract-basis-card-heading i { color: #246445; }
.contract-basis-grid label { display: grid; gap: 6px; color: #465149; font-size: .6875rem; font-weight: 800; }
.contract-basis-grid select,
.contract-basis-grid input:not([type="file"]) { width: 100%; min-height: 42px; border: 1px solid #bcc6c0; border-radius: 4px; background: #fff; padding: 9px 10px; color: #1f2924; font: inherit; }
.contract-basis-grid select:focus,
.contract-basis-grid input:focus { outline: 3px solid #8f352e1c; border-color: #8f352e; }
.contract-basis-upload-row { display: grid; grid-template-columns: 1fr auto; gap: 8px; }
.contract-basis-upload,
.contract-basis-upload-row > button,
.contract-basis-remove,
.contract-basis-selected a {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #aeb8b2;
  border-radius: 4px;
  background: #fff;
  padding: 8px 10px;
  color: #303a35;
  font-size: .625rem;
  font-weight: 850;
  text-decoration: none;
  cursor: pointer;
}
.contract-basis-upload input { display: none; }
.contract-basis-upload-row > button:disabled,
.contract-basis-upload:has(input:disabled),
.contract-basis-remove:disabled { cursor: default; opacity: .55; }
.contract-basis-selected { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 10px; border-left: 3px solid #313a35; background: #eef2ef; padding: 10px; }
.contract-basis-selected > div { min-width: 0; display: grid; gap: 3px; }
.contract-basis-selected strong,
.contract-basis-selected small { overflow-wrap: anywhere; }
.contract-basis-selected strong { font-size: .75rem; }
.contract-basis-selected small { color: #657069; font-size: .5625rem; }
.contract-basis-selected a { min-height: 32px; }
.contract-basis-remove { justify-self: start; border-color: transparent; background: transparent; color: #843c36; padding-inline: 0; }
.contract-basis-panel > footer { border-top: 1px solid #dfe3e0; padding-top: 12px; }

.owner-contract-basis { display: grid; gap: 11px; border: 1px solid #cfd6d1; border-left: 4px solid #303a35; border-radius: 10px; background: #fff; padding: 15px; }
.owner-contract-basis > header { display: flex; justify-content: space-between; gap: 14px; }
.owner-contract-basis h2 { margin: 0 0 4px; font-size: .875rem; }
.owner-contract-basis header p,
.owner-contract-basis footer { margin: 0; color: #69736d; font-size: .5rem; line-height: 1.5; }
.owner-contract-basis > header > b { color: #3c4741; font-size: .4375rem; letter-spacing: .06em; }
.owner-contract-basis > div { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.owner-contract-basis article { display: grid; grid-template-columns: 34px 1fr auto; align-items: center; gap: 10px; border: 1px solid #dce1dd; border-radius: 8px; background: #f7f9f7; padding: 11px; }
.owner-contract-basis article > span { width: 32px; height: 32px; display: grid; place-items: center; border: 1px solid #929e97; border-radius: 4px; color: #303a35; font-size: .5rem; font-weight: 950; }
.owner-contract-basis article > div { min-width: 0; display: grid; gap: 2px; }
.owner-contract-basis article strong { color: #657069; font-size: .4375rem; letter-spacing: .04em; text-transform: uppercase; }
.owner-contract-basis article b { overflow-wrap: anywhere; font-size: .625rem; }
.owner-contract-basis article small { color: #6d7671; font-size: .5rem; }
.owner-contract-basis article button { min-height: 34px; border: 1px solid #c9d0cb; border-radius: 5px; background: #fff; padding: 0 10px; color: #7f352f; font-size: .5rem; font-weight: 900; }

@media (max-width: 900px) {
  .contract-basis-grid,
  .owner-contract-basis > div { grid-template-columns: 1fr; }
}
@media (max-width: 560px) {
  .contract-basis-panel > header,
  .contract-basis-selected,
  .owner-contract-basis article { grid-template-columns: 1fr; display: grid; }
  .contract-basis-upload-row { grid-template-columns: 1fr; }
  .contract-basis-selected a,
  .owner-contract-basis article button { width: 100%; }
}
/* Controlled project bonus records reflow within the current work panel. */
.project-bonus-controls{min-width:0;margin-block:.75rem;padding:.85rem;border:1px solid var(--border,#d5dce2);border-radius:.5rem;background:var(--panel,#fff);color:var(--text,#17212b)}
.project-bonus-controls>header{display:flex;align-items:flex-start;justify-content:space-between;gap:.65rem;flex-wrap:wrap}
.project-bonus-controls>header>div:first-child{display:grid;gap:.3rem;min-width:0}
.project-bonus-controls span,.project-bonus-controls strong,.project-bonus-controls small,.project-bonus-controls a{overflow-wrap:anywhere}
.project-bonus-controls>header span,.bonus-people span{font-size:.875rem}
.bonus-facts,.bonus-people{display:flex;gap:.5rem 1.5rem;flex-wrap:wrap;margin-block:.65rem}
.bonus-people>div{display:grid;gap:.2rem;flex:1 1 16rem;min-width:0}
.bonus-warning{font-size:.875rem;color:#8b241e;margin:.65rem 0}
.bonus-preview{display:block;width:100%;max-width:100%;height:36rem;border:1px solid #ccd2d9;margin:.75rem 0}
.bonus-edit-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,16rem),1fr));gap:.75rem;margin:.8rem 0}
.bonus-sign-form{display:grid;gap:.75rem;margin:.8rem 0;max-width:42rem}
.bonus-edit-form label,.bonus-sign-form>label:not(.turnover-check){display:grid;gap:.3rem;min-width:0;font-size:.875rem}
.bonus-edit-form input,.bonus-edit-form select,.bonus-edit-form textarea,.bonus-sign-form input{width:100%;min-width:0;max-width:100%;padding:.5rem;border:1px solid #bfc9d3;border-radius:.3rem;background:#fff;color:#17212b;font:inherit;box-sizing:border-box}
.bonus-wide{grid-column:1/-1}
.bonus-edit-form small{line-height:1.5}
.bonus-history summary{cursor:pointer;font-size:.875rem;padding:.45rem 0}
.bonus-history article{display:flex;gap:.5rem 1rem;flex-wrap:wrap;padding:.5rem 0;border-top:1px solid #e0e4e8;font-size:.875rem}
.bonus-history article span{flex:1 1 20rem;min-width:0}
.bonus-loading{font-size:.875rem;padding:.5rem}
.project-bonus-controls .turnover-buttons{display:flex;align-items:center;flex-wrap:wrap;gap:.5rem;min-width:0;max-width:100%}
.project-bonus-controls .turnover-buttons>*{max-width:100%;white-space:normal;text-align:center}
.project-bonus-controls .turnover-check{display:flex;align-items:flex-start;gap:.5rem;font-size:.875rem;line-height:1.5}
.project-bonus-controls .turnover-check input[type="checkbox"]{width:1.1rem;flex:0 0 1.1rem;margin:.2rem 0}
.project-bonus-controls .primary-action,.project-bonus-controls .secondary-action{display:inline-flex;align-items:center;justify-content:center;min-height:2.5rem;gap:.4rem;padding:.5rem .75rem;font-size:.875rem;font-weight:600;line-height:1.35;text-decoration:none;border-radius:.4rem}
.project-bonus-controls .secondary-action{border:1px solid #cbd1d7;background:#fff;color:#29343c}
.project-bonus-controls .primary-action{border:1px solid #922e26;background:#922e26;color:#fff}
.project-bonus-controls button:disabled{opacity:.55;cursor:not-allowed}
.nav-subitem{grid-template-columns:1.625rem minmax(0,1fr)}
.nav-subitem>span[aria-hidden="true"]{white-space:nowrap;overflow-wrap:normal;word-break:normal}
.plaid-connections { min-width: 0; }
.plaid-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: .65rem; }
.plaid-toolbar h2, .plaid-toolbar h3 { flex: 1 1 16rem; margin: 0; }
.plaid-toolbar button, .plaid-account-assignment button { flex-shrink: 0; max-width: 100%; white-space: normal; }
.plaid-add-account, .plaid-item { margin-top: 1rem; padding: 1rem; border: 1px solid var(--border, #d6dce4); border-radius: .5rem; }
.plaid-add-account label, .plaid-account-assignment label { display: grid; gap: .4rem; font-size: .875rem; min-width: 0; }
.plaid-add-account label { max-width: 24rem; margin: .8rem 0; }
.plaid-account-list { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 20rem), 1fr)); gap: 1rem; margin-top: 1rem; }
.plaid-account { min-width: 0; padding: .8rem; background: var(--surface-subtle, #f6f8fb); border-radius: .4rem; overflow-wrap: anywhere; }
.plaid-account h4 { font-size: .9375rem; margin: 0 0 .4rem; }
.plaid-secondary { font-size: .75rem; color: #536174; }
.plaid-account dl { display: flex; flex-wrap: wrap; gap: .75rem 1.5rem; }
.plaid-account dt { font-size: .75rem; }
.plaid-account dd { margin: .2rem 0 0; font-size: 1rem; font-weight: 600; }
.plaid-account-assignment { display: flex; align-items: end; flex-wrap: wrap; gap: .6rem; }
.plaid-account-assignment label { flex: 1 1 12rem; }
.plaid-account-assignment select, .plaid-add-account input { width: 100%; min-width: 0; font-size: .875rem; }
.plaid-feed { display: grid; gap: .5rem; }
.plaid-feed article { display: flex; flex-wrap: wrap; gap: .4rem 1rem; padding: .75rem 0; border-bottom: 1px solid #d6dce4; font-size: .875rem; overflow-wrap: anywhere; }
.plaid-feed strong { flex: 1 1 15rem; }
.plaid-disconnect { margin-top: .75rem; }
.plaid-oauth-return { max-width: 42rem; padding: 1.5rem; margin: auto; }
